window.GUIDES = {
  "ur": "\n    <style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:13.5px}\n      .guide-content th,.guide-content td{text-align:center;padding:6px 8px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n      .guide-content .twrap{overflow-x:auto;margin:12px 0}\n      .guide-content .twrap table{margin:0;min-width:420px}\n    </style>\n\n    <h2>اندازے کے بغیر انگوٹھی کے سائز کا چارٹ پڑھنا</h2>\n    <p>آن لائن خریداری میں انگوٹھی کا سائز سب سے زیادہ الجھا دینے والی چیزوں میں سے ایک ہے: امریکہ/کینیڈا، برطانیہ/آسٹریلیا، یورپی یونین اور جاپان/کوریا کے نظام الگ الگ انداز میں گنتی کرتے ہیں، اور کوئی بھی سادہ ذہنی حساب سے دوسرے میں تبدیل نہیں ہوتا۔ یہ کنورٹر اندازے کے بجائے آپ کا سائز براہِ راست شائع شدہ سائز چارٹ میں دیکھتا ہے — وہی اعداد جو اصل انگوٹھیوں کے اندر کندہ ہوتے ہیں — نہ کہ کسی تخمینی فارمولے سے حساب لگاتا ہے۔</p>\n\n    <h2>انگوٹھی کے سائز کے نظام کس طرح مختلف ہیں</h2>\n    <ul>\n      <li><strong>امریکہ / کینیڈا</strong> تقریباً 3 سے 16 تک عددی پیمانہ استعمال کرتا ہے، جس کے درمیان آدھے سائز بھی ہوتے ہیں (ایک مکمل سائز کا فرق قطر میں تقریباً 0.4 ملی میٹر بنتا ہے)۔</li>\n      <li><strong>برطانیہ / آسٹریلیا / آئرلینڈ</strong> A سے Z تک حروف استعمال کرتا ہے، جہاں زیادہ تر ملحقہ امریکی آدھے سائزوں کے درمیان آدھے حرف (½) کا فرق آتا ہے۔</li>\n      <li><strong>یورپی یونین (ISO 8653)</strong> کی تعریف انگلی کے گھیر کے طور پر ملی میٹر میں کی جاتی ہے — یعنی یورپی سائز 54 کا لفظی مطلب 54 ملی میٹر گھیر ہے، اس مرحلے کے لیے کسی چارٹ کی ضرورت نہیں۔</li>\n      <li><strong>جاپان / کوریا (号)</strong> اپنا الگ بڑھتا ہوا عددی پیمانہ استعمال کرتے ہیں، تقریباً ہر 1.3 ملی میٹر گھیر پر ایک اکائی؛ اہم بات یہ ہے کہ جاپان اور کوریا کے اعداد بالکل ایک جیسے ہیں، اس لیے جاپانی 号14 اور کوریائی 14호 ایک ہی انگوٹھی ہیں۔</li>\n      <li><strong>اندرونی قطر (ملی میٹر)</strong> سوراخ کے گرد کا فاصلہ نہیں بلکہ اس کے آر پار سیدھی چوڑائی ہے — یہ اُس وقت کارآمد ہے جب آپ انگلی کے بجائے پہلے سے موجود انگوٹھی ناپ رہے ہوں۔</li>\n    </ul>\n\n    <div class=\"example\">\n      <p><strong>حل شدہ مثال۔</strong> امریکی سائز 7 کی انگوٹھی برطانیہ میں N½ ہے، اس کا یورپی گھیر 54.4 ملی میٹر ہے، جاپان/کوریا میں 号14 ہے، اور اندرونی قطر 17.3 ملی میٹر ہے — چاروں اعداد بعینہٖ ایک ہی جسمانی سوراخ کو بیان کرتے ہیں، بس گننے کا انداز مختلف ہے۔</p>\n    </div>\n\n    <h2>انگوٹھی کے سائز کی مکمل تبدیلی کا چارٹ</h2>\n    <p>یہ وہی مکمل اقدار ہیں جو یہ کنورٹر استعمال کرتا ہے — یہی اعداد اوپر دیے گئے انٹرایکٹو ٹول کو چلاتے ہیں، اس لیے وہاں \"مجھے اپنا سائز اِس نظام میں معلوم ہے\" بدلنے پر نتیجہ ہمیشہ نیچے کی کسی سطر سے مطابقت رکھتا ہے۔</p>\n    <div class=\"twrap\">\n    <table>\n      <thead><tr><th>امریکہ / کینیڈا</th><th>برطانیہ / آسٹریلیا</th><th>یورپی یونین (ملی میٹر)</th><th>جاپان / کوریا (号)</th><th>قطر (ملی میٹر)</th></tr></thead>\n      <tbody>\n        <tr><td>3</td><td>F</td><td>44.0</td><td>4</td><td>14.1</td></tr>\n        <tr><td>3.5</td><td>G</td><td>45.5</td><td>5</td><td>14.5</td></tr>\n        <tr><td>4</td><td>H</td><td>46.8</td><td>7</td><td>14.9</td></tr>\n        <tr><td>4.5</td><td>I</td><td>48.0</td><td>8</td><td>15.3</td></tr>\n        <tr><td>5</td><td>J½</td><td>49.3</td><td>9</td><td>15.7</td></tr>\n        <tr><td>5.5</td><td>K½</td><td>50.6</td><td>10</td><td>16.1</td></tr>\n        <tr><td>6</td><td>L½</td><td>51.9</td><td>12</td><td>16.5</td></tr>\n        <tr><td>6.5</td><td>M½</td><td>53.1</td><td>13</td><td>16.9</td></tr>\n        <tr><td>7</td><td>N½</td><td>54.4</td><td>14</td><td>17.3</td></tr>\n        <tr><td>7.5</td><td>O½</td><td>55.7</td><td>15</td><td>17.7</td></tr>\n        <tr><td>8</td><td>P½</td><td>57.0</td><td>17</td><td>18.1</td></tr>\n        <tr><td>8.5</td><td>Q½</td><td>58.3</td><td>18</td><td>18.5</td></tr>\n        <tr><td>9</td><td>R½</td><td>59.5</td><td>19</td><td>18.9</td></tr>\n        <tr><td>9.5</td><td>S½</td><td>60.8</td><td>21</td><td>19.3</td></tr>\n        <tr><td>10</td><td>T½</td><td>62.1</td><td>22</td><td>19.7</td></tr>\n        <tr><td>10.5</td><td>U½</td><td>63.4</td><td>23</td><td>20.1</td></tr>\n        <tr><td>11</td><td>V½</td><td>64.6</td><td>24</td><td>20.5</td></tr>\n        <tr><td>11.5</td><td>W½</td><td>65.9</td><td>26</td><td>20.9</td></tr>\n        <tr><td>12</td><td>X½</td><td>67.2</td><td>27</td><td>21.3</td></tr>\n        <tr><td>12.5</td><td>Y½</td><td>68.5</td><td>28</td><td>21.7</td></tr>\n        <tr><td>13</td><td>Z½</td><td>69.7</td><td>29</td><td>22.2</td></tr>\n      </tbody>\n    </table>\n    </div>\n    <p>یہ چارٹ آدھے سائزوں کی اُس حد کا احاطہ کرتا ہے جس میں بالغوں کی زیادہ تر انگوٹھیاں فروخت ہوتی ہیں (تقریباً چھوٹے زنانہ سائز سے بڑے مردانہ سائز تک)۔ اگر آپ کی پیمائش اس سے ذرا باہر نکل جائے تو اوپر والا کنورٹر جواب دینے سے انکار کرنے کے بجائے قریب ترین مطابق سطر دکھا دیتا ہے۔</p>\n\n    <h2>گھر پر انگوٹھی کا سائز کیسے ناپیں</h2>\n    <h3>طریقہ 1: دھاگہ یا کاغذ کی پٹی (گھیر ناپتا ہے)</h3>\n    <ol>\n      <li>کاغذ کی ایک باریک پٹی کاٹ لیں، یا ایسا دھاگہ یا ربن استعمال کریں جو کھنچتا نہ ہو۔</li>\n      <li>جس انگلی میں انگوٹھی پہننی ہے اس کی جڑ کے گرد اسے کس کر لپیٹیں — اتنا کسا کہ ٹکا رہے، اور اتنا ڈھیلا کہ پور کے اوپر سے گزر جائے۔</li>\n      <li>قلم سے ٹھیک وہ نقطہ نشان زد کریں جہاں پٹی خود پر آ کر ملتی ہے۔</li>\n      <li>پٹی کو سیدھا بچھا کر نشان تک لمبائی پیمانے سے ملی میٹر میں ناپیں۔</li>\n      <li>امریکہ، برطانیہ اور جاپان/کوریا کے مطابق سائز دیکھنے کے لیے یہ عدد اوپر یورپی یونین (گھیر، ملی میٹر) کے خانے میں درج کریں۔</li>\n    </ol>\n    <h3>طریقہ 2: پہلے سے پوری آنے والی انگوٹھی (اندرونی قطر ناپتا ہے)</h3>\n    <ol>\n      <li>ایسی انگوٹھی چنیں جو مطلوبہ انگلی میں پہلے ہی آرام سے آتی ہو — کسی دوسری انگلی میں پہنی جانے والی انگوٹھی نہیں، اور نہ ہی بہت چوڑی بھاری انگوٹھی، جو اسی سائز کے باریک بینڈ کی نسبت زیادہ تنگ بیٹھتی ہے۔</li>\n      <li>انگوٹھی کو پیمانے پر، یا قابلِ پرنٹ رِنگ سائزنگ چارٹ پر ہموار رکھیں۔</li>\n      <li>اندرونی سوراخ کو اس کے سب سے چوڑے مقام پر سیدھی لکیر میں ملی میٹر میں ناپیں۔</li>\n      <li>امریکہ، برطانیہ، یورپی یونین اور جاپان/کوریا کے مطابق سائز دیکھنے کے لیے یہ عدد اوپر اندرونی قطر (ملی میٹر) کے خانے میں درج کریں۔</li>\n    </ol>\n\n    <h2>درست سائز حاصل کرنے کے مشورے</h2>\n    <ul>\n      <li><strong>دن کا وقت اہم ہے:</strong> دن گزرنے کے ساتھ اور گرم موسم میں انگلیاں ہلکی سی پھول جاتی ہیں، جبکہ سردی میں سکڑ جاتی ہیں۔ روزمرہ کے سب سے قابلِ اعتماد سائز کے لیے شام کو ناپیں، اور ورزش کے فوراً بعد یا سرد موسم میں ناپنے سے گریز کریں۔</li>\n      <li><strong>عین وہی انگلی ناپیں:</strong> ایک ہی ہاتھ کی مختلف انگلیوں کے درمیان، حتیٰ کہ بائیں اور دائیں ہاتھ کے درمیان بھی، انگوٹھی کا سائز نمایاں طور پر مختلف ہو سکتا ہے۔</li>\n      <li><strong>چوڑے بینڈ کو اضافی گنجائش چاہیے:</strong> تقریباً 6 ملی میٹر سے چوڑے بینڈ کو باریک بینڈ جیسا احساس دینے کے لیے عموماً آدھا سائز بڑا درکار ہوتا ہے، کیونکہ انگلی سے زیادہ دھات لگتی ہے۔</li>\n      <li><strong>دو سائزوں کے بیچ میں ہیں؟</strong> بڑا سائز لینا عموماً محفوظ رہتا ہے — ذرا ڈھیلی انگوٹھی کو چھوٹا کروانا، بہت تنگ انگوٹھی کو کھلوانے کی نسبت آسان (اور سستا) ہوتا ہے۔</li>\n    </ul>\n\n    <h2>عام چارٹ پیشہ ورانہ پیمائش کا متبادل کیوں نہیں</h2>\n    <p>جوتوں یا کپڑوں کے سائز کے برعکس، انگوٹھی بغیر کسی گنجائش کے براہِ راست جلد سے لگی رہتی ہے، اس لیے پیمائش کی معمولی غلطی بھی زیادہ اثر ڈالتی ہے۔ اس کنورٹر کا چارٹ زیورات کی صنعت میں رائج معیاری جدولوں سے مطابقت رکھتا ہے، مگر پور کا حجم، انگلی کی ساخت، اور کسی مخصوص انگوٹھی کی چوڑائی و دھات — یہ سب آرام دہ محسوس ہونے والے سائز کو آدھے سائز تک سرکا سکتے ہیں۔ کسی اہم خریداری کے لیے — خاص طور پر منگنی کی انگوٹھی کے لیے — جوہری کے دھاتی رِنگ سائزر کو خود پہن کر دیکھنا دھاگے یا چھپے ہوئے چارٹ سے ہمیشہ زیادہ قابلِ اعتماد ہے۔</p>\n",
  "id": "\n    <style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:13.5px}\n      .guide-content th,.guide-content td{text-align:center;padding:6px 8px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n      .guide-content .twrap{overflow-x:auto;margin:12px 0}\n      .guide-content .twrap table{margin:0;min-width:420px}\n    </style>\n\n    <h2>Membaca tabel ukuran cincin tanpa menebak-nebak</h2>\n    <p>Ukuran cincin termasuk hal yang paling membingungkan saat belanja online: sistem AS/Kanada, Inggris/Australia, Uni Eropa, dan Jepang/Korea menghitung dengan cara berbeda, dan tak satu pun bisa dikonversi ke yang lain lewat hitungan sederhana di kepala. Konverter ini menghilangkan tebak-tebakan dengan mencari ukuran Anda langsung di tabel ukuran cincin resmi — angka yang sama seperti yang tertera di bagian dalam cincin sungguhan — alih-alih menghitungnya dengan rumus perkiraan.</p>\n\n    <h2>Perbedaan antar sistem ukuran cincin</h2>\n    <ul>\n      <li><strong>AS / Kanada</strong> memakai skala angka dari sekitar 3 hingga 16, dengan setengah ukuran di antaranya (satu langkah ukuran penuh setara sekitar 0,4 mm diameter).</li>\n      <li><strong>Inggris / Australia / Irlandia</strong> memakai huruf A sampai Z, dengan langkah setengah huruf (½) di antara sebagian besar setengah ukuran AS yang berdekatan.</li>\n      <li><strong>Uni Eropa (ISO 8653)</strong> didefinisikan sebagai lingkar jari dalam milimeter — jadi ukuran EU 54 secara harfiah berarti lingkar 54 mm, tanpa perlu tabel untuk langkah itu sendiri.</li>\n      <li><strong>Jepang / Korea (号)</strong> memakai skala angka menaik tersendiri, kira-kira satu satuan per 1,3 mm lingkar; yang penting, Jepang dan Korea memakai angka yang persis sama, sehingga 号14 Jepang dan 14호 Korea adalah cincin yang sama.</li>\n      <li><strong>Diameter dalam (mm)</strong> adalah lebar lubang secara garis lurus, bukan jarak keliling — berguna saat Anda mengukur cincin yang sudah ada alih-alih jari Anda.</li>\n    </ul>\n\n    <div class=\"example\">\n      <p><strong>Contoh perhitungan.</strong> Cincin ukuran AS 7 setara N½ di Inggris, berlingkar EU 54,4 mm, ukuran Jepang/Korea 号14, dan berdiameter dalam 17,3 mm — keempat angka itu menggambarkan lubang cincin fisik yang sama persis, hanya dihitung dengan cara berbeda.</p>\n    </div>\n\n    <h2>Tabel konversi ukuran cincin lengkap</h2>\n    <p>Inilah nilai acuan lengkap yang dipakai konverter ini — angka yang sama menggerakkan alat interaktif di atas, jadi mengubah pilihan \"Saya tahu ukuran saya dalam\" di sana selalu cocok dengan salah satu baris di bawah.</p>\n    <div class=\"twrap\">\n    <table>\n      <thead><tr><th>AS / Kanada</th><th>Inggris / Australia</th><th>Uni Eropa (mm)</th><th>Jepang / Korea (号)</th><th>Diameter (mm)</th></tr></thead>\n      <tbody>\n        <tr><td>3</td><td>F</td><td>44.0</td><td>4</td><td>14.1</td></tr>\n        <tr><td>3.5</td><td>G</td><td>45.5</td><td>5</td><td>14.5</td></tr>\n        <tr><td>4</td><td>H</td><td>46.8</td><td>7</td><td>14.9</td></tr>\n        <tr><td>4.5</td><td>I</td><td>48.0</td><td>8</td><td>15.3</td></tr>\n        <tr><td>5</td><td>J½</td><td>49.3</td><td>9</td><td>15.7</td></tr>\n        <tr><td>5.5</td><td>K½</td><td>50.6</td><td>10</td><td>16.1</td></tr>\n        <tr><td>6</td><td>L½</td><td>51.9</td><td>12</td><td>16.5</td></tr>\n        <tr><td>6.5</td><td>M½</td><td>53.1</td><td>13</td><td>16.9</td></tr>\n        <tr><td>7</td><td>N½</td><td>54.4</td><td>14</td><td>17.3</td></tr>\n        <tr><td>7.5</td><td>O½</td><td>55.7</td><td>15</td><td>17.7</td></tr>\n        <tr><td>8</td><td>P½</td><td>57.0</td><td>17</td><td>18.1</td></tr>\n        <tr><td>8.5</td><td>Q½</td><td>58.3</td><td>18</td><td>18.5</td></tr>\n        <tr><td>9</td><td>R½</td><td>59.5</td><td>19</td><td>18.9</td></tr>\n        <tr><td>9.5</td><td>S½</td><td>60.8</td><td>21</td><td>19.3</td></tr>\n        <tr><td>10</td><td>T½</td><td>62.1</td><td>22</td><td>19.7</td></tr>\n        <tr><td>10.5</td><td>U½</td><td>63.4</td><td>23</td><td>20.1</td></tr>\n        <tr><td>11</td><td>V½</td><td>64.6</td><td>24</td><td>20.5</td></tr>\n        <tr><td>11.5</td><td>W½</td><td>65.9</td><td>26</td><td>20.9</td></tr>\n        <tr><td>12</td><td>X½</td><td>67.2</td><td>27</td><td>21.3</td></tr>\n        <tr><td>12.5</td><td>Y½</td><td>68.5</td><td>28</td><td>21.7</td></tr>\n        <tr><td>13</td><td>Z½</td><td>69.7</td><td>29</td><td>22.2</td></tr>\n      </tbody>\n    </table>\n    </div>\n    <p>Tabel ini mencakup rentang setengah ukuran tempat sebagian besar cincin dewasa dijual (kira-kira dari ukuran wanita kecil sampai ukuran pria besar). Jika hasil pengukuran Anda sedikit di luar rentang itu, konverter di atas menampilkan baris terdekat yang cocok, bukan menolak menjawab.</p>\n\n    <h2>Cara mengukur ukuran cincin di rumah</h2>\n    <h3>Metode 1: benang atau potongan kertas (mengukur lingkar)</h3>\n    <ol>\n      <li>Potong selembar kertas tipis memanjang, atau gunakan benang maupun pita yang tidak melar.</li>\n      <li>Lilitkan pas di pangkal jari yang akan dipakaikan cincin — cukup pas agar tidak lepas, tetapi cukup longgar untuk melewati buku jari.</li>\n      <li>Tandai dengan pena titik tepat tempat kedua ujung lilitan bertemu.</li>\n      <li>Bentangkan potongan itu dan ukur panjang sampai tanda menggunakan penggaris, dalam milimeter.</li>\n      <li>Masukkan angka tersebut ke kolom Uni Eropa (lingkar, mm) di atas untuk melihat ukuran AS, Inggris, dan Jepang/Korea yang sepadan.</li>\n    </ol>\n    <h3>Metode 2: cincin yang sudah pas (mengukur diameter dalam)</h3>\n    <ol>\n      <li>Pilih cincin yang sudah pas dan nyaman di jari yang dituju — bukan cincin yang dipakai di jari lain, dan bukan cincin lebar bergaya statement, yang terasa lebih sempit daripada cincin tipis berukuran sama.</li>\n      <li>Letakkan cincin mendatar di atas penggaris, atau di atas tabel pengukur cincin yang bisa dicetak.</li>\n      <li>Ukur lubang bagian dalam secara garis lurus pada titik terlebarnya, dalam milimeter.</li>\n      <li>Masukkan angka tersebut ke kolom Diameter dalam (mm) di atas untuk melihat ukuran AS, Inggris, Uni Eropa, dan Jepang/Korea yang sepadan.</li>\n    </ol>\n\n    <h2>Kiat mendapatkan ukuran yang akurat</h2>\n    <ul>\n      <li><strong>Waktu pengukuran berpengaruh:</strong> jari sedikit membengkak sepanjang hari dan saat cuaca panas, lalu menyusut saat dingin. Ukurlah pada malam hari untuk mendapat ukuran harian paling andal, dan hindari mengukur tepat setelah berolahraga atau saat cuaca dingin.</li>\n      <li><strong>Ukur jari yang tepat:</strong> ukuran cincin bisa berbeda cukup jelas antar jari pada tangan yang sama, bahkan antara tangan kiri dan kanan.</li>\n      <li><strong>Cincin lebar butuh ruang ekstra:</strong> cincin dengan lebar di atas sekitar 6 mm umumnya perlu setengah ukuran lebih besar daripada cincin tipis agar terasa sama, karena lebih banyak logam yang menyentuh jari.</li>\n      <li><strong>Berada di antara dua ukuran?</strong> Mengambil ukuran lebih besar biasanya lebih aman — cincin yang sedikit longgar lebih mudah (dan lebih murah) dikecilkan daripada cincin terlalu sempit yang harus dilebarkan.</li>\n    </ul>\n\n    <h2>Mengapa tabel umum bukan pengganti pengukuran profesional</h2>\n    <p>Berbeda dengan ukuran sepatu atau pakaian, cincin menempel langsung di kulit tanpa kelonggaran, sehingga kesalahan pengukuran kecil pun lebih terasa. Tabel konverter ini sesuai dengan tabel acuan standar yang dipakai di industri perhiasan, tetapi ukuran buku jari, bentuk jari, serta lebar dan jenis logam cincin tertentu semuanya dapat menggeser rasa nyaman sebesar setengah ukuran. Untuk pembelian penting — apalagi cincin tunangan — alat ukur cincin logam milik toko perhiasan yang dicoba langsung selalu lebih andal daripada benang atau tabel cetak.</p>\n",
  "bn": "\n    <style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:13.5px}\n      .guide-content th,.guide-content td{text-align:center;padding:6px 8px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n      .guide-content .twrap{overflow-x:auto;margin:12px 0}\n      .guide-content .twrap table{margin:0;min-width:420px}\n    </style>\n\n    <h2>আন্দাজ ছাড়াই আংটির মাপের চার্ট পড়া</h2>\n    <p>অনলাইনে কেনাকাটার সবচেয়ে বিভ্রান্তিকর বিষয়গুলোর একটি হলো আংটির মাপ: যুক্তরাষ্ট্র/কানাডা, যুক্তরাজ্য/অস্ট্রেলিয়া, ইইউ এবং জাপান/কোরিয়ার পদ্ধতিগুলো আলাদাভাবে গোনে, আর সাধারণ মুখে-মুখে হিসাবে একটিকে অন্যটিতে রূপান্তর করা যায় না। এই কনভার্টার আন্দাজের বদলে আপনার মাপ সরাসরি প্রকাশিত আংটির মাপের চার্টে খুঁজে দেখে — যে সংখ্যাগুলোই আসল আংটির ভেতরে খোদাই করা থাকে — কোনো আনুমানিক সূত্রে হিসাব করে না।</p>\n\n    <h2>আংটির মাপের পদ্ধতিগুলো কীভাবে আলাদা</h2>\n    <ul>\n      <li><strong>যুক্তরাষ্ট্র / কানাডা</strong> মোটামুটি 3 থেকে 16 পর্যন্ত সংখ্যাভিত্তিক স্কেল ব্যবহার করে, মাঝখানে অর্ধ-মাপসহ (এক পূর্ণ মাপের ধাপ ব্যাসে প্রায় 0.4 মিমি)।</li>\n      <li><strong>যুক্তরাজ্য / অস্ট্রেলিয়া / আয়ারল্যান্ড</strong> A থেকে Z পর্যন্ত অক্ষর ব্যবহার করে, যেখানে পাশাপাশি বেশিরভাগ মার্কিন অর্ধ-মাপের মাঝে অর্ধ-অক্ষরের (½) ধাপ থাকে।</li>\n      <li><strong>ইইউ (ISO 8653)</strong> সংজ্ঞায়িত হয় আঙুলের পরিধি হিসেবে, মিলিমিটারে — অর্থাৎ ইইউ মাপ 54 মানে আক্ষরিকভাবেই 54 মিমি পরিধি, এই ধাপে আলাদা চার্ট লাগে না।</li>\n      <li><strong>জাপান / কোরিয়া (号)</strong> নিজস্ব ঊর্ধ্বক্রমিক সংখ্যা-স্কেল ব্যবহার করে, পরিধির প্রতি 1.3 মিমিতে মোটামুটি এক একক; গুরুত্বপূর্ণ বিষয় হলো জাপান ও কোরিয়ার সংখ্যা হুবহু এক, তাই জাপানি 号14 আর কোরীয় 14호 একই আংটি।</li>\n      <li><strong>ভেতরের ব্যাস (মিমি)</strong> হলো ফাঁকা জায়গার সরলরৈখিক প্রস্থ, চারপাশের দূরত্ব নয় — আঙুলের বদলে আগে থেকে থাকা আংটি মাপার সময় এটি কাজে লাগে।</li>\n    </ul>\n\n    <div class=\"example\">\n      <p><strong>উদাহরণসহ হিসাব।</strong> মার্কিন মাপ 7-এর আংটি যুক্তরাজ্যে N½, এর ইইউ পরিধি 54.4 মিমি, জাপান/কোরিয়ায় 号14, এবং ভেতরের ব্যাস 17.3 মিমি — চারটি সংখ্যাই একই বাস্তব ফাঁকা মাপকে বোঝায়, শুধু গোনার ধরন আলাদা।</p>\n    </div>\n\n    <h2>আংটির মাপ রূপান্তরের পূর্ণ চার্ট</h2>\n    <p>এই কনভার্টার যে সম্পূর্ণ লুকআপ মানগুলো ব্যবহার করে সেগুলোই এখানে দেওয়া — একই সংখ্যাগুলো উপরের ইন্টারঅ্যাক্টিভ টুলটিকে চালায়, তাই সেখানে \"আমি আমার মাপ জানি\" পদ্ধতিটি বদলালে ফলাফল সবসময় নিচের কোনো এক সারির সঙ্গে মেলে।</p>\n    <div class=\"twrap\">\n    <table>\n      <thead><tr><th>যুক্তরাষ্ট্র / কানাডা</th><th>যুক্তরাজ্য / অস্ট্রেলিয়া</th><th>ইইউ (মিমি)</th><th>জাপান / কোরিয়া (号)</th><th>ব্যাস (মিমি)</th></tr></thead>\n      <tbody>\n        <tr><td>3</td><td>F</td><td>44.0</td><td>4</td><td>14.1</td></tr>\n        <tr><td>3.5</td><td>G</td><td>45.5</td><td>5</td><td>14.5</td></tr>\n        <tr><td>4</td><td>H</td><td>46.8</td><td>7</td><td>14.9</td></tr>\n        <tr><td>4.5</td><td>I</td><td>48.0</td><td>8</td><td>15.3</td></tr>\n        <tr><td>5</td><td>J½</td><td>49.3</td><td>9</td><td>15.7</td></tr>\n        <tr><td>5.5</td><td>K½</td><td>50.6</td><td>10</td><td>16.1</td></tr>\n        <tr><td>6</td><td>L½</td><td>51.9</td><td>12</td><td>16.5</td></tr>\n        <tr><td>6.5</td><td>M½</td><td>53.1</td><td>13</td><td>16.9</td></tr>\n        <tr><td>7</td><td>N½</td><td>54.4</td><td>14</td><td>17.3</td></tr>\n        <tr><td>7.5</td><td>O½</td><td>55.7</td><td>15</td><td>17.7</td></tr>\n        <tr><td>8</td><td>P½</td><td>57.0</td><td>17</td><td>18.1</td></tr>\n        <tr><td>8.5</td><td>Q½</td><td>58.3</td><td>18</td><td>18.5</td></tr>\n        <tr><td>9</td><td>R½</td><td>59.5</td><td>19</td><td>18.9</td></tr>\n        <tr><td>9.5</td><td>S½</td><td>60.8</td><td>21</td><td>19.3</td></tr>\n        <tr><td>10</td><td>T½</td><td>62.1</td><td>22</td><td>19.7</td></tr>\n        <tr><td>10.5</td><td>U½</td><td>63.4</td><td>23</td><td>20.1</td></tr>\n        <tr><td>11</td><td>V½</td><td>64.6</td><td>24</td><td>20.5</td></tr>\n        <tr><td>11.5</td><td>W½</td><td>65.9</td><td>26</td><td>20.9</td></tr>\n        <tr><td>12</td><td>X½</td><td>67.2</td><td>27</td><td>21.3</td></tr>\n        <tr><td>12.5</td><td>Y½</td><td>68.5</td><td>28</td><td>21.7</td></tr>\n        <tr><td>13</td><td>Z½</td><td>69.7</td><td>29</td><td>22.2</td></tr>\n      </tbody>\n    </table>\n    </div>\n    <p>এই চার্ট প্রাপ্তবয়স্কদের বেশিরভাগ আংটি যে অর্ধ-মাপের পরিসরে বিক্রি হয় তা কভার করে (মোটামুটি ছোট নারীর মাপ থেকে বড় পুরুষের মাপ পর্যন্ত)। আপনার মাপ যদি এর সামান্য বাইরে পড়ে, উপরের কনভার্টার উত্তর দিতে অস্বীকার না করে সবচেয়ে কাছের মিলযুক্ত সারিটি দেখায়।</p>\n\n    <h2>ঘরে বসে আংটির মাপ কীভাবে নেবেন</h2>\n    <h3>পদ্ধতি ১: সুতো বা কাগজের ফালি (পরিধি মাপে)</h3>\n    <ol>\n      <li>কাগজের সরু একটি ফালি কাটুন, অথবা টান-না-খাওয়া সুতো বা ফিতা ব্যবহার করুন।</li>\n      <li>যে আঙুলে আংটি পরবেন তার গোড়ায় এটি আঁটসাঁটভাবে জড়ান — এতটা আঁট যেন খুলে না যায়, আবার এতটা ঢিলে যেন গাঁট পেরিয়ে যায়।</li>\n      <li>কলম দিয়ে ঠিক যে বিন্দুতে ফালিটি নিজের ওপর এসে মেলে সেখানে দাগ দিন।</li>\n      <li>ফালিটি সমতলে বিছিয়ে দাগ পর্যন্ত দৈর্ঘ্য স্কেলে মিলিমিটারে মাপুন।</li>\n      <li>যুক্তরাষ্ট্র, যুক্তরাজ্য ও জাপান/কোরিয়ার মিল-করা মাপ দেখতে সংখ্যাটি উপরের ইইউ (পরিধি, মিমি) ঘরে লিখুন।</li>\n    </ol>\n    <h3>পদ্ধতি ২: আগে থেকেই ফিট হওয়া আংটি (ভেতরের ব্যাস মাপে)</h3>\n    <ol>\n      <li>এমন একটি আংটি নিন যা নির্দিষ্ট আঙুলে আগে থেকেই আরামে ফিট হয় — অন্য আঙুলে পরা আংটি নয়, আর খুব চওড়া ভারী আংটিও নয়, কারণ একই মাপের সরু ব্যান্ডের চেয়ে সেটি আঁট বসে।</li>\n      <li>আংটিটি স্কেলের ওপর, কিংবা প্রিন্ট করা রিং-সাইজিং চার্টের ওপর সমতলভাবে রাখুন।</li>\n      <li>ভেতরের ফাঁকা অংশ তার সবচেয়ে চওড়া জায়গায় সরলরেখায় মিলিমিটারে মাপুন।</li>\n      <li>যুক্তরাষ্ট্র, যুক্তরাজ্য, ইইউ ও জাপান/কোরিয়ার মিল-করা মাপ দেখতে সংখ্যাটি উপরের ভেতরের ব্যাস (মিমি) ঘরে লিখুন।</li>\n    </ol>\n\n    <h2>নির্ভুল মাপ পাওয়ার পরামর্শ</h2>\n    <ul>\n      <li><strong>দিনের সময় গুরুত্বপূর্ণ:</strong> দিন গড়ানোর সঙ্গে ও গরম আবহাওয়ায় আঙুল সামান্য ফোলে, আর ঠান্ডায় সঙ্কুচিত হয়। দৈনন্দিন ব্যবহারের সবচেয়ে নির্ভরযোগ্য মাপের জন্য সন্ধ্যায় মাপুন, আর ব্যায়ামের ঠিক পরে বা ঠান্ডা আবহাওয়ায় মাপা এড়িয়ে চলুন।</li>\n      <li><strong>ঠিক সেই আঙুলটিই মাপুন:</strong> একই হাতের বিভিন্ন আঙুলে, এমনকি বাঁ ও ডান হাতের মধ্যেও আংটির মাপ লক্ষণীয়ভাবে আলাদা হতে পারে।</li>\n      <li><strong>চওড়া ব্যান্ডে বাড়তি জায়গা লাগে:</strong> প্রায় 6 মিমির চেয়ে চওড়া ব্যান্ডে সরু ব্যান্ডের মতো অনুভূতি পেতে সাধারণত অর্ধ মাপ বড় লাগে, কারণ আঙুলে বেশি ধাতু স্পর্শ করে।</li>\n      <li><strong>দুই মাপের মাঝামাঝি?</strong> সাধারণত বড় মাপ নেওয়াই নিরাপদ — সামান্য ঢিলে আংটি ছোট করানো, খুব আঁট আংটি বড় করার চেয়ে সহজ (ও সস্তা)।</li>\n    </ul>\n\n    <h2>সাধারণ চার্ট কেন পেশাদার মাপের বিকল্প নয়</h2>\n    <p>জুতো বা পোশাকের মাপের বিপরীতে, আংটি কোনো বাড়তি ঢিলেমি ছাড়াই সরাসরি ত্বক স্পর্শ করে, তাই সামান্য মাপের ভুলও বেশি প্রভাব ফেলে। এই কনভার্টারের চার্ট গয়না শিল্পে ব্যবহৃত আদর্শ লুকআপ টেবিলের সঙ্গে মেলে, তবে গাঁটের আকার, আঙুলের গড়ন এবং নির্দিষ্ট আংটির প্রস্থ ও ধাতু — সবই আরামদায়ক অনুভূতিকে অর্ধ মাপ পর্যন্ত সরিয়ে দিতে পারে। গুরুত্বপূর্ণ কেনাকাটায় — বিশেষত বাগদানের আংটিতে — জুয়েলারের ধাতব রিং সাইজার সরাসরি পরে দেখা সুতো বা ছাপা চার্টের চেয়ে সবসময়ই বেশি নির্ভরযোগ্য।</p>\n",
  "hi": "\n    <style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:13.5px}\n      .guide-content th,.guide-content td{text-align:center;padding:6px 8px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n      .guide-content .twrap{overflow-x:auto;margin:12px 0}\n      .guide-content .twrap table{margin:0;min-width:420px}\n    </style>\n\n    <h2>अंदाज़े के बिना रिंग साइज़ चार्ट पढ़ना</h2>\n    <p>ऑनलाइन खरीदारी में अंगूठी का नाप सबसे उलझाने वाली चीज़ों में से एक है: अमेरिका/कनाडा, यूके/ऑस्ट्रेलिया, ईयू और जापान/कोरिया की प्रणालियाँ अलग-अलग तरीके से गिनती करती हैं, और इनमें से कोई भी साधारण मन-ही-मन गणित से दूसरी में नहीं बदलती। यह कन्वर्टर अनुमान लगाने के बजाय आपका नाप सीधे प्रकाशित रिंग साइज़ चार्ट में देखता है — वही अंक जो असली अंगूठियों के भीतर अंकित होते हैं — न कि किसी अनुमानित सूत्र से गणना करता है।</p>\n\n    <h2>रिंग साइज़िंग प्रणालियाँ किस तरह अलग हैं</h2>\n    <ul>\n      <li><strong>अमेरिका / कनाडा</strong> लगभग 3 से 16 तक का संख्यात्मक पैमाना इस्तेमाल करता है, बीच में आधे नाप के साथ (एक पूरे नाप का अंतर व्यास में लगभग 0.4 मिमी होता है)।</li>\n      <li><strong>यूके / ऑस्ट्रेलिया / आयरलैंड</strong> A से Z तक के अक्षर इस्तेमाल करता है, जिसमें अधिकांश आसपास के अमेरिकी आधे नापों के बीच आधे अक्षर (½) का अंतर होता है।</li>\n      <li><strong>ईयू (ISO 8653)</strong> को उंगली की परिधि के रूप में मिलीमीटर में परिभाषित किया गया है — यानी ईयू नाप 54 का शाब्दिक अर्थ 54 मिमी परिधि है, इस चरण के लिए किसी चार्ट की ज़रूरत नहीं।</li>\n      <li><strong>जापान / कोरिया (号)</strong> अपना ही बढ़ता हुआ संख्यात्मक पैमाना इस्तेमाल करते हैं, मोटे तौर पर परिधि के हर 1.3 मिमी पर एक इकाई; ख़ास बात यह है कि जापान और कोरिया के अंक बिलकुल एक जैसे हैं, इसलिए जापानी 号14 और कोरियाई 14호 एक ही अंगूठी हैं।</li>\n      <li><strong>भीतरी व्यास (मिमी)</strong> छेद के चारों ओर की दूरी नहीं, बल्कि उसके आर-पार की सीधी चौड़ाई है — यह तब काम आता है जब आप उंगली के बजाय पहले से मौजूद अंगूठी नाप रहे हों।</li>\n    </ul>\n\n    <div class=\"example\">\n      <p><strong>हल किया गया उदाहरण।</strong> अमेरिकी नाप 7 की अंगूठी यूके में N½ होती है, उसकी ईयू परिधि 54.4 मिमी है, जापान/कोरिया में 号14 है और भीतरी व्यास 17.3 मिमी है — चारों अंक ठीक उसी एक भौतिक छेद का वर्णन करते हैं, बस गिनने का तरीका अलग है।</p>\n    </div>\n\n    <h2>पूरा रिंग साइज़ रूपांतरण चार्ट</h2>\n    <p>ये वही पूर्ण लुकअप मान हैं जिनका उपयोग यह कन्वर्टर करता है — यही अंक ऊपर दिए गए इंटरैक्टिव टूल को चलाते हैं, इसलिए वहाँ \"मुझे अपना नाप इस प्रणाली में पता है\" बदलने पर परिणाम हमेशा नीचे की किसी पंक्ति से मेल खाता है।</p>\n    <div class=\"twrap\">\n    <table>\n      <thead><tr><th>अमेरिका / कनाडा</th><th>यूके / ऑस्ट्रेलिया</th><th>ईयू (मिमी)</th><th>जापान / कोरिया (号)</th><th>व्यास (मिमी)</th></tr></thead>\n      <tbody>\n        <tr><td>3</td><td>F</td><td>44.0</td><td>4</td><td>14.1</td></tr>\n        <tr><td>3.5</td><td>G</td><td>45.5</td><td>5</td><td>14.5</td></tr>\n        <tr><td>4</td><td>H</td><td>46.8</td><td>7</td><td>14.9</td></tr>\n        <tr><td>4.5</td><td>I</td><td>48.0</td><td>8</td><td>15.3</td></tr>\n        <tr><td>5</td><td>J½</td><td>49.3</td><td>9</td><td>15.7</td></tr>\n        <tr><td>5.5</td><td>K½</td><td>50.6</td><td>10</td><td>16.1</td></tr>\n        <tr><td>6</td><td>L½</td><td>51.9</td><td>12</td><td>16.5</td></tr>\n        <tr><td>6.5</td><td>M½</td><td>53.1</td><td>13</td><td>16.9</td></tr>\n        <tr><td>7</td><td>N½</td><td>54.4</td><td>14</td><td>17.3</td></tr>\n        <tr><td>7.5</td><td>O½</td><td>55.7</td><td>15</td><td>17.7</td></tr>\n        <tr><td>8</td><td>P½</td><td>57.0</td><td>17</td><td>18.1</td></tr>\n        <tr><td>8.5</td><td>Q½</td><td>58.3</td><td>18</td><td>18.5</td></tr>\n        <tr><td>9</td><td>R½</td><td>59.5</td><td>19</td><td>18.9</td></tr>\n        <tr><td>9.5</td><td>S½</td><td>60.8</td><td>21</td><td>19.3</td></tr>\n        <tr><td>10</td><td>T½</td><td>62.1</td><td>22</td><td>19.7</td></tr>\n        <tr><td>10.5</td><td>U½</td><td>63.4</td><td>23</td><td>20.1</td></tr>\n        <tr><td>11</td><td>V½</td><td>64.6</td><td>24</td><td>20.5</td></tr>\n        <tr><td>11.5</td><td>W½</td><td>65.9</td><td>26</td><td>20.9</td></tr>\n        <tr><td>12</td><td>X½</td><td>67.2</td><td>27</td><td>21.3</td></tr>\n        <tr><td>12.5</td><td>Y½</td><td>68.5</td><td>28</td><td>21.7</td></tr>\n        <tr><td>13</td><td>Z½</td><td>69.7</td><td>29</td><td>22.2</td></tr>\n      </tbody>\n    </table>\n    </div>\n    <p>यह चार्ट आधे नापों की उस श्रेणी को कवर करता है जिसमें अधिकतर वयस्क अंगूठियाँ बिकती हैं (लगभग छोटे महिला नाप से लेकर बड़े पुरुष नाप तक)। यदि आपका माप इससे थोड़ा बाहर पड़ता है, तो ऊपर का कन्वर्टर जवाब देने से इनकार करने के बजाय सबसे नज़दीकी मेल खाती पंक्ति दिखा देता है।</p>\n\n    <h2>घर पर अपनी अंगूठी का नाप कैसे लें</h2>\n    <h3>तरीक़ा 1: धागा या काग़ज़ की पट्टी (परिधि नापता है)</h3>\n    <ol>\n      <li>काग़ज़ की एक पतली पट्टी काटें, या ऐसा धागा या रिबन लें जो खिंचता न हो।</li>\n      <li>जिस उंगली में अंगूठी पहननी है उसके निचले हिस्से के चारों ओर इसे कसकर लपेटें — इतना कसा कि टिका रहे, और इतना ढीला कि पोर के ऊपर से निकल जाए।</li>\n      <li>पेन से ठीक वह जगह चिह्नित करें जहाँ पट्टी ख़ुद पर आकर मिलती है।</li>\n      <li>पट्टी को सीधा फैलाकर चिह्नित लंबाई को स्केल से मिलीमीटर में नापें।</li>\n      <li>अमेरिका, यूके और जापान/कोरिया के मेल खाते नाप देखने के लिए वह संख्या ऊपर ईयू (परिधि, मिमी) खाने में डालें।</li>\n    </ol>\n    <h3>तरीक़ा 2: पहले से फ़िट आती अंगूठी (भीतरी व्यास नापता है)</h3>\n    <ol>\n      <li>ऐसी अंगूठी चुनें जो उसी उंगली में पहले से आराम से आती हो — किसी दूसरी उंगली में पहनी जाने वाली अंगूठी नहीं, और न ही बहुत चौड़ी भारी अंगूठी, जो उसी नाप के पतले बैंड से ज़्यादा कसी बैठती है।</li>\n      <li>अंगूठी को स्केल पर, या प्रिंट किए जा सकने वाले रिंग-साइज़िंग चार्ट पर सपाट रखें।</li>\n      <li>भीतरी छेद को उसके सबसे चौड़े स्थान पर सीधे आर-पार मिलीमीटर में नापें।</li>\n      <li>अमेरिका, यूके, ईयू और जापान/कोरिया के मेल खाते नाप देखने के लिए वह संख्या ऊपर भीतरी व्यास (मिमी) खाने में डालें।</li>\n    </ol>\n\n    <h2>सही नाप पाने के सुझाव</h2>\n    <ul>\n      <li><strong>दिन का समय मायने रखता है:</strong> दिन चढ़ने के साथ और गर्म मौसम में उंगलियाँ थोड़ी फूल जाती हैं, और ठंड में सिकुड़ती हैं। रोज़मर्रा के लिए सबसे भरोसेमंद नाप पाने हेतु शाम को नापें, और कसरत के तुरंत बाद या ठंड में नापने से बचें।</li>\n      <li><strong>ठीक उसी उंगली को नापें:</strong> एक ही हाथ की अलग-अलग उंगलियों के बीच, और बाएँ-दाएँ हाथ के बीच भी, अंगूठी का नाप उल्लेखनीय रूप से अलग हो सकता है।</li>\n      <li><strong>चौड़े बैंड को अतिरिक्त जगह चाहिए:</strong> लगभग 6 मिमी से चौड़े बैंड को पतले बैंड जैसा एहसास देने के लिए आमतौर पर आधा नाप बड़ा चाहिए, क्योंकि उंगली से ज़्यादा धातु छूती है।</li>\n      <li><strong>दो नापों के बीच हैं?</strong> बड़ा नाप लेना आमतौर पर सुरक्षित रहता है — थोड़ी ढीली अंगूठी को छोटा करवाना, बहुत कसी अंगूठी को फैलाने की तुलना में ज़्यादा आसान (और सस्ता) होता है।</li>\n    </ul>\n\n    <h2>सामान्य चार्ट पेशेवर नाप का विकल्प क्यों नहीं है</h2>\n    <p>जूते या कपड़ों के नाप के विपरीत, अंगूठी बिना किसी ढील के सीधे त्वचा से लगी रहती है, इसलिए मापन की छोटी-सी चूक भी ज़्यादा असर डालती है। इस कन्वर्टर का चार्ट आभूषण उद्योग में इस्तेमाल होने वाली मानक लुकअप तालिकाओं से मेल खाता है, लेकिन पोर का आकार, उंगली की बनावट, और किसी ख़ास अंगूठी की सटीक चौड़ाई व धातु — ये सब आरामदेह लगने वाले नाप को आधे नाप तक खिसका सकते हैं। किसी अहम ख़रीद के लिए — ख़ासकर सगाई की अंगूठी के लिए — जौहरी के धातु के रिंग साइज़र को ख़ुद पहनकर देखना धागे या छपे चार्ट से हमेशा ज़्यादा भरोसेमंद है।</p>\n",
  "ar": "\n    <style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:13.5px}\n      .guide-content th,.guide-content td{text-align:center;padding:6px 8px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n      .guide-content .twrap{overflow-x:auto;margin:12px 0}\n      .guide-content .twrap table{margin:0;min-width:420px}\n    </style>\n\n    <h2>قراءة جدول مقاسات الخواتم دون تخمين</h2>\n    <p>يُعدّ مقاس الخاتم من أكثر الأمور إرباكًا عند الشراء عبر الإنترنت: فأنظمة الولايات المتحدة/كندا، وبريطانيا/أستراليا، والاتحاد الأوروبي، واليابان/كوريا يَعدّ كل منها بطريقة مختلفة، ولا يمكن تحويل أيٍّ منها إلى الآخر بحساب ذهني بسيط. يتجاوز هذا المحوِّل التخمين بالبحث عن مقاسك مباشرةً في جدول مقاسات منشور — وهي الأرقام نفسها المحفورة داخل الخواتم الحقيقية — بدلًا من حسابه بمعادلة تقريبية.</p>\n\n    <h2>كيف تختلف أنظمة مقاسات الخواتم</h2>\n    <ul>\n      <li><strong>الولايات المتحدة / كندا</strong> تستخدم مقياسًا رقميًا يمتد تقريبًا من 3 إلى 16، مع أنصاف مقاسات بينها (خطوة المقاس الكامل تعادل نحو 0.4 مم من القطر).</li>\n      <li><strong>بريطانيا / أستراليا / أيرلندا</strong> تستخدم الحروف من A إلى Z، بخطوة نصف حرف (½) بين معظم أنصاف المقاسات الأمريكية المتجاورة.</li>\n      <li><strong>الاتحاد الأوروبي (ISO 8653)</strong> يُعرَّف بأنه محيط الإصبع بالمليمتر — أي أن المقاس الأوروبي 54 يعني حرفيًا محيطًا مقداره 54 مم، دون حاجة إلى جدول في هذه الخطوة تحديدًا.</li>\n      <li><strong>اليابان / كوريا (号)</strong> تستخدمان مقياسًا رقميًا تصاعديًا خاصًا بهما، بواقع وحدة واحدة تقريبًا لكل 1.3 مم من المحيط؛ والأهم أن اليابان وكوريا تشتركان في الأرقام نفسها تمامًا، فالمقاس الياباني 号14 والكوري 14호 هما الخاتم ذاته.</li>\n      <li><strong>القطر الداخلي (مم)</strong> هو عرض الفتحة بخط مستقيم وليس المسافة حولها — وهو مفيد عند قياس خاتم موجود لديك بدلًا من قياس إصبعك.</li>\n    </ul>\n\n    <div class=\"example\">\n      <p><strong>مثال محلول.</strong> الخاتم بالمقاس الأمريكي 7 يعادل N½ في بريطانيا، ومحيطًا أوروبيًا مقداره 54.4 مم، والمقاس الياباني/الكوري 号14، وقطرًا داخليًا مقداره 17.3 مم — الأرقام الأربعة كلها تصف فتحة الخاتم المادية نفسها، لكن بطرق عدّ مختلفة.</p>\n    </div>\n\n    <h2>جدول تحويل مقاسات الخواتم الكامل</h2>\n    <p>هذه هي قيم الجدول الكاملة التي يستخدمها هذا المحوِّل — وهي الأرقام نفسها التي تُغذّي الأداة التفاعلية أعلاه، لذا فإن تغيير النظام في خانة «أعرف مقاسي بنظام» يطابق دائمًا أحد الصفوف أدناه.</p>\n    <div class=\"twrap\">\n    <table>\n      <thead><tr><th>الولايات المتحدة / كندا</th><th>بريطانيا / أستراليا</th><th>الاتحاد الأوروبي (مم)</th><th>اليابان / كوريا (号)</th><th>القطر (مم)</th></tr></thead>\n      <tbody>\n        <tr><td>3</td><td>F</td><td>44.0</td><td>4</td><td>14.1</td></tr>\n        <tr><td>3.5</td><td>G</td><td>45.5</td><td>5</td><td>14.5</td></tr>\n        <tr><td>4</td><td>H</td><td>46.8</td><td>7</td><td>14.9</td></tr>\n        <tr><td>4.5</td><td>I</td><td>48.0</td><td>8</td><td>15.3</td></tr>\n        <tr><td>5</td><td>J½</td><td>49.3</td><td>9</td><td>15.7</td></tr>\n        <tr><td>5.5</td><td>K½</td><td>50.6</td><td>10</td><td>16.1</td></tr>\n        <tr><td>6</td><td>L½</td><td>51.9</td><td>12</td><td>16.5</td></tr>\n        <tr><td>6.5</td><td>M½</td><td>53.1</td><td>13</td><td>16.9</td></tr>\n        <tr><td>7</td><td>N½</td><td>54.4</td><td>14</td><td>17.3</td></tr>\n        <tr><td>7.5</td><td>O½</td><td>55.7</td><td>15</td><td>17.7</td></tr>\n        <tr><td>8</td><td>P½</td><td>57.0</td><td>17</td><td>18.1</td></tr>\n        <tr><td>8.5</td><td>Q½</td><td>58.3</td><td>18</td><td>18.5</td></tr>\n        <tr><td>9</td><td>R½</td><td>59.5</td><td>19</td><td>18.9</td></tr>\n        <tr><td>9.5</td><td>S½</td><td>60.8</td><td>21</td><td>19.3</td></tr>\n        <tr><td>10</td><td>T½</td><td>62.1</td><td>22</td><td>19.7</td></tr>\n        <tr><td>10.5</td><td>U½</td><td>63.4</td><td>23</td><td>20.1</td></tr>\n        <tr><td>11</td><td>V½</td><td>64.6</td><td>24</td><td>20.5</td></tr>\n        <tr><td>11.5</td><td>W½</td><td>65.9</td><td>26</td><td>20.9</td></tr>\n        <tr><td>12</td><td>X½</td><td>67.2</td><td>27</td><td>21.3</td></tr>\n        <tr><td>12.5</td><td>Y½</td><td>68.5</td><td>28</td><td>21.7</td></tr>\n        <tr><td>13</td><td>Z½</td><td>69.7</td><td>29</td><td>22.2</td></tr>\n      </tbody>\n    </table>\n    </div>\n    <p>يغطي هذا الجدول نطاق أنصاف المقاسات الذي تُباع فيه معظم خواتم البالغين (من مقاس نسائي صغير تقريبًا حتى مقاس رجالي كبير). وإذا وقع قياسك خارجه قليلًا، فسيعرض المحوِّل أعلاه أقرب صف مطابق بدلًا من رفض الإجابة.</p>\n\n    <h2>كيف تقيس مقاس خاتمك في المنزل</h2>\n    <h3>الطريقة الأولى: خيط أو شريط ورقي (تقيس المحيط)</h3>\n    <ol>\n      <li>قصّ شريطًا رفيعًا من الورق، أو استخدم خيطًا أو شريطة لا تتمدد.</li>\n      <li>لفّه بإحكام حول قاعدة الإصبع الذي سترتدي فيه الخاتم — محكمًا بما يكفي ليثبت، ومرتخيًا بما يكفي ليمرّ فوق المفصل.</li>\n      <li>علّم بالقلم النقطة التي يتلاقى عندها طرفا الشريط بالضبط.</li>\n      <li>افرد الشريط على سطح مستوٍ وقِس الطول المعلَّم بمسطرة، بالمليمتر.</li>\n      <li>أدخل هذا الرقم في خانة الاتحاد الأوروبي (المحيط، مم) أعلاه لترى المقاسات المقابلة في الولايات المتحدة وبريطانيا واليابان/كوريا.</li>\n    </ol>\n    <h3>الطريقة الثانية: خاتم لديك بالفعل ومقاسه مناسب (تقيس القطر الداخلي)</h3>\n    <ol>\n      <li>اختر خاتمًا يناسب بالفعل الإصبع المقصود براحة — لا خاتمًا يُلبس في إصبع آخر، ولا خاتمًا عريضًا جدًا، فهو يضيق أكثر من حلقة رفيعة بالمقاس نفسه.</li>\n      <li>ضع الخاتم مسطحًا على مسطرة أو على جدول قياس خواتم قابل للطباعة.</li>\n      <li>قِس الفتحة الداخلية بخط مستقيم عند أوسع نقطة، بالمليمتر.</li>\n      <li>أدخل هذا الرقم في خانة القطر الداخلي (مم) أعلاه لترى المقاسات المقابلة في الولايات المتحدة وبريطانيا والاتحاد الأوروبي واليابان/كوريا.</li>\n    </ol>\n\n    <h2>نصائح للحصول على مقاس دقيق</h2>\n    <ul>\n      <li><strong>وقت القياس مهم:</strong> تنتفخ الأصابع قليلًا مع تقدم اليوم وفي الطقس الحار، وتنكمش في البرد. قِس في المساء للحصول على أوثق مقاس يومي، وتجنّب القياس بعد التمرين مباشرةً أو في الجو البارد.</li>\n      <li><strong>قِس الإصبع المقصود تحديدًا:</strong> قد يختلف مقاس الخاتم اختلافًا ملحوظًا بين أصابع اليد الواحدة، بل وبين يدك اليمنى واليسرى.</li>\n      <li><strong>الحلقات العريضة تحتاج مساحة إضافية:</strong> الحلقة التي يزيد عرضها عن نحو 6 مم تحتاج عادةً إلى نصف مقاس أكبر من الحلقة الرفيعة لتعطي الإحساس نفسه، لأن معدنًا أكثر يلامس الإصبع.</li>\n      <li><strong>بين مقاسين؟</strong> اختيار المقاس الأكبر أكثر أمانًا عادةً — فالخاتم الواسع قليلًا يسهل تصغيره (وبتكلفة أقل) أكثر مما يسهل توسيع خاتم ضيق.</li>\n    </ul>\n\n    <h2>لماذا لا يغني الجدول العام عن القياس الاحترافي</h2>\n    <p>على عكس مقاسات الأحذية أو الملابس، يلامس الخاتم الجلد مباشرةً دون أي هامش راحة، لذا فأخطاء القياس الصغيرة أشد تأثيرًا. يطابق جدول هذا المحوِّل جداول البحث المعيارية المعتمدة في قطاع المجوهرات، لكن حجم المفصل وشكل الإصبع وعرض الخاتم ومعدنه تحديدًا قد تُزيح جميعها الإحساس بالراحة بمقدار نصف مقاس. أما في عملية شراء مهمة — وخصوصًا خاتم الخطوبة — فإن أدوات القياس المعدنية لدى الصائغ، وتجربتها شخصيًا، تظل أوثق دائمًا من خيط أو جدول مطبوع.</p>\n",
  "ru": "\n    <style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:13.5px}\n      .guide-content th,.guide-content td{text-align:center;padding:6px 8px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n      .guide-content .twrap{overflow-x:auto;margin:12px 0}\n      .guide-content .twrap table{margin:0;min-width:420px}\n    </style>\n\n\n    <h2>Как читать таблицу размеров колец без догадок</h2>\n    <p>Размер кольца — одна из самых запутанных вещей при покупках онлайн: системы США/Канады, Великобритании/Австралии, ЕС и Японии/Кореи считают по-разному, и ни одна не переводится в другую простым устным счётом. Этот конвертер избавляет от догадок: он ищет ваш размер прямо в опубликованной таблице размеров — тех самых числах, что выгравированы внутри настоящих колец, — а не рассчитывает приблизительную формулу.</p>\n\n    <h2>Чем различаются системы размеров колец</h2>\n    <ul>\n      <li><strong>США / Канада</strong> использует числовую шкалу примерно от 3 до 16 с половинными размерами между ними (шаг в один полный размер — около 0,4 мм диаметра).</li>\n      <li><strong>Великобритания / Австралия / Ирландия</strong> использует буквы от A до Z, где между большинством соседних американских половинных размеров укладывается шаг в полбуквы (½).</li>\n      <li><strong>ЕС (ISO 8653)</strong> определяется как окружность пальца в миллиметрах — то есть европейский размер 54 буквально означает окружность 54 мм, и на этом шаге таблица не нужна.</li>\n      <li><strong>Япония / Корея (号)</strong> использует собственную возрастающую числовую шкалу — примерно одна единица на 1,3 мм окружности; важно, что Япония и Корея используют абсолютно одинаковые числа, поэтому японский 号14 и корейский 14호 — это одно и то же кольцо.</li>\n      <li><strong>Внутренний диаметр (мм)</strong> — это ширина отверстия по прямой, а не расстояние вокруг него; удобно, когда вы измеряете уже имеющееся кольцо, а не палец.</li>\n    </ul>\n\n    <div class=\"example\">\n      <p><strong>Разбор примера.</strong> Кольцо американского размера 7 — это британский N½, европейская окружность 54,4 мм, японский/корейский 号14 и внутренний диаметр 17,3 мм: все четыре числа описывают одно и то же физическое отверстие кольца, просто посчитанное по-разному.</p>\n    </div>\n\n    <h2>Полная таблица перевода размеров колец</h2>\n    <p>Это полный набор справочных значений, которые использует конвертер, — те же числа питают интерактивный инструмент выше, поэтому при смене системы в поле «Я знаю свой размер в» результат всегда соответствует одной из строк ниже.</p>\n<div class=\"twrap\">\n    <table>\n      <thead><tr><th>미국 / 캐나다</th><th>영국 / 호주</th><th>유럽 (mm)</th><th>일본 / 한국 (호)</th><th>안지름 (mm)</th></tr></thead>\n      <tbody>\n        <tr><td>3</td><td>F</td><td>44.0</td><td>4</td><td>14.1</td></tr>\n        <tr><td>3.5</td><td>G</td><td>45.5</td><td>5</td><td>14.5</td></tr>\n        <tr><td>4</td><td>H</td><td>46.8</td><td>7</td><td>14.9</td></tr>\n        <tr><td>4.5</td><td>I</td><td>48.0</td><td>8</td><td>15.3</td></tr>\n        <tr><td>5</td><td>J½</td><td>49.3</td><td>9</td><td>15.7</td></tr>\n        <tr><td>5.5</td><td>K½</td><td>50.6</td><td>10</td><td>16.1</td></tr>\n        <tr><td>6</td><td>L½</td><td>51.9</td><td>12</td><td>16.5</td></tr>\n        <tr><td>6.5</td><td>M½</td><td>53.1</td><td>13</td><td>16.9</td></tr>\n        <tr><td>7</td><td>N½</td><td>54.4</td><td>14</td><td>17.3</td></tr>\n        <tr><td>7.5</td><td>O½</td><td>55.7</td><td>15</td><td>17.7</td></tr>\n        <tr><td>8</td><td>P½</td><td>57.0</td><td>17</td><td>18.1</td></tr>\n        <tr><td>8.5</td><td>Q½</td><td>58.3</td><td>18</td><td>18.5</td></tr>\n        <tr><td>9</td><td>R½</td><td>59.5</td><td>19</td><td>18.9</td></tr>\n        <tr><td>9.5</td><td>S½</td><td>60.8</td><td>21</td><td>19.3</td></tr>\n        <tr><td>10</td><td>T½</td><td>62.1</td><td>22</td><td>19.7</td></tr>\n        <tr><td>10.5</td><td>U½</td><td>63.4</td><td>23</td><td>20.1</td></tr>\n        <tr><td>11</td><td>V½</td><td>64.6</td><td>24</td><td>20.5</td></tr>\n        <tr><td>11.5</td><td>W½</td><td>65.9</td><td>26</td><td>20.9</td></tr>\n        <tr><td>12</td><td>X½</td><td>67.2</td><td>27</td><td>21.3</td></tr>\n        <tr><td>12.5</td><td>Y½</td><td>68.5</td><td>28</td><td>21.7</td></tr>\n        <tr><td>13</td><td>Z½</td><td>69.7</td><td>29</td><td>22.2</td></tr>\n      </tbody>\n    </table>\n    </div>\n    <p>Таблица охватывает диапазон половинных размеров, в котором продаётся большинство взрослых колец (примерно от небольшого женского до крупного мужского). Если ваше измерение чуть выходит за эти границы, конвертер выше покажет ближайшую подходящую строку, а не откажется отвечать.</p>\n\n    <h2>Как измерить размер кольца дома</h2>\n    <h3>Способ 1: нитка или бумажная полоска (измеряет окружность)</h3>\n    <ol>\n      <li>Вырежьте узкую полоску бумаги либо возьмите нитку или ленту, которая не тянется.</li>\n      <li>Плотно оберните её вокруг основания того пальца, на котором будете носить кольцо, — достаточно плотно, чтобы держалось, и достаточно свободно, чтобы проходило через сустав.</li>\n      <li>Отметьте ручкой точное место, где полоска смыкается сама с собой.</li>\n      <li>Расправьте полоску и измерьте отмеченную длину линейкой в миллиметрах.</li>\n      <li>Введите это число в поле «ЕС (окружность, мм)» выше, чтобы увидеть соответствующие размеры США, Великобритании и Японии/Кореи.</li>\n    </ol>\n    <h3>Способ 2: кольцо, которое уже подходит (измеряет внутренний диаметр)</h3>\n    <ol>\n      <li>Возьмите кольцо, которое уже удобно сидит на нужном пальце, — не кольцо с другого пальца и не очень широкое массивное кольцо, которое сидит теснее тонкого того же размера.</li>\n      <li>Положите кольцо плашмя на линейку или на распечатанный шаблон для измерения колец.</li>\n      <li>Измерьте по прямой внутреннее отверстие в самом широком месте, в миллиметрах.</li>\n      <li>Введите это число в поле «Внутренний диаметр (мм)» выше, чтобы увидеть соответствующие размеры США, Великобритании, ЕС и Японии/Кореи.</li>\n    </ol>\n\n    <h2>Советы для точного измерения</h2>\n    <ul>\n      <li><strong>Время суток имеет значение:</strong> к вечеру и в жару пальцы слегка отекают, а на холоде сужаются. Измеряйте вечером, чтобы получить самый надёжный повседневный размер, и не измеряйте сразу после тренировки или на холоде.</li>\n      <li><strong>Измеряйте именно тот палец:</strong> размер кольца может заметно отличаться у разных пальцев одной руки и даже между левой и правой рукой.</li>\n      <li><strong>Широкой шинке нужен запас:</strong> кольцу шириной более 6 мм обычно требуется на полразмера больше, чем тонкому, чтобы ощущаться так же, ведь пальца касается больше металла.</li>\n      <li><strong>Между двумя размерами?</strong> Обычно безопаснее взять больший: слегка свободное кольцо уменьшить проще (и дешевле), чем растянуть слишком тесное.</li>\n    </ul>\n\n    <h2>Почему общая таблица не заменяет профессиональное измерение</h2>\n    <p>В отличие от размеров обуви или одежды, кольцо напрямую касается кожи без всякого запаса свободы, поэтому небольшие погрешности измерения ощущаются сильнее. Таблица этого конвертера соответствует стандартным справочным таблицам ювелирной отрасли, но размер сустава, форма пальца, а также точная ширина и металл конкретного кольца могут сместить комфортный размер на полразмера. Для важной покупки — особенно помолвочного кольца — металлический набор мерных колец у ювелира, примеренный лично, всегда надёжнее нитки или распечатанной таблицы.</p>\n",
  "pt": "\n    <style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:13.5px}\n      .guide-content th,.guide-content td{text-align:center;padding:6px 8px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n      .guide-content .twrap{overflow-x:auto;margin:12px 0}\n      .guide-content .twrap table{margin:0;min-width:420px}\n    </style>\n\n\n    <h2>Como ler uma tabela de tamanhos de anel sem adivinhação</h2>\n    <p>O tamanho de anel é uma das coisas mais confusas de comprar pela internet: os sistemas dos EUA/Canadá, Reino Unido/Austrália, UE e Japão/Coreia contam de formas diferentes, e nenhum se converte em outro com uma conta simples de cabeça. Este conversor elimina a adivinhação consultando o seu tamanho diretamente em uma tabela publicada — os mesmos números gravados no interior de anéis reais — em vez de aplicar uma fórmula aproximada.</p>\n\n    <h2>Como os sistemas de numeração de anéis diferem</h2>\n    <ul>\n      <li><strong>EUA / Canadá</strong> usa uma escala numérica de cerca de 3 a 16, com meios-tamanhos intermediários (um tamanho inteiro corresponde a cerca de 0,4 mm de diâmetro).</li>\n      <li><strong>Reino Unido / Austrália / Irlanda</strong> usa as letras A a Z, com um passo de meia letra (½) entre a maioria dos meios-tamanhos norte-americanos adjacentes.</li>\n      <li><strong>UE (ISO 8653)</strong> é definido como a circunferência do dedo em milímetros — ou seja, um tamanho UE 54 significa literalmente 54 mm de circunferência, sem precisar de consulta nessa etapa.</li>\n      <li><strong>Japão / Coreia (号)</strong> usa a própria escala numérica crescente, com cerca de uma unidade por 1,3 mm de circunferência; e, o que é essencial, Japão e Coreia usam exatamente os mesmos números, então um 号14 japonês e um 14호 coreano são o mesmo anel.</li>\n      <li><strong>Diâmetro interno (mm)</strong> é a largura em linha reta da abertura, e não a distância ao redor dela — útil quando você mede um anel que já tem, em vez do dedo.</li>\n    </ul>\n\n    <div class=\"example\">\n      <p><strong>Exemplo prático.</strong> Um anel tamanho 7 dos EUA equivale ao N½ britânico, tem circunferência UE de 54,4 mm, é um 号14 do Japão/Coreia e tem 17,3 mm de diâmetro interno — os quatro números descrevem exatamente a mesma abertura física, apenas contada de maneiras diferentes.</p>\n    </div>\n\n    <h2>Tabela completa de conversão de tamanhos de anel</h2>\n    <p>Estes são os valores completos de consulta usados por este conversor — os mesmos números alimentam a ferramenta interativa acima, de modo que mudar o sistema em \"Sei meu tamanho em\" sempre corresponde a uma linha abaixo.</p>\n<div class=\"twrap\">\n    <table>\n      <thead><tr><th>미국 / 캐나다</th><th>영국 / 호주</th><th>유럽 (mm)</th><th>일본 / 한국 (호)</th><th>안지름 (mm)</th></tr></thead>\n      <tbody>\n        <tr><td>3</td><td>F</td><td>44.0</td><td>4</td><td>14.1</td></tr>\n        <tr><td>3.5</td><td>G</td><td>45.5</td><td>5</td><td>14.5</td></tr>\n        <tr><td>4</td><td>H</td><td>46.8</td><td>7</td><td>14.9</td></tr>\n        <tr><td>4.5</td><td>I</td><td>48.0</td><td>8</td><td>15.3</td></tr>\n        <tr><td>5</td><td>J½</td><td>49.3</td><td>9</td><td>15.7</td></tr>\n        <tr><td>5.5</td><td>K½</td><td>50.6</td><td>10</td><td>16.1</td></tr>\n        <tr><td>6</td><td>L½</td><td>51.9</td><td>12</td><td>16.5</td></tr>\n        <tr><td>6.5</td><td>M½</td><td>53.1</td><td>13</td><td>16.9</td></tr>\n        <tr><td>7</td><td>N½</td><td>54.4</td><td>14</td><td>17.3</td></tr>\n        <tr><td>7.5</td><td>O½</td><td>55.7</td><td>15</td><td>17.7</td></tr>\n        <tr><td>8</td><td>P½</td><td>57.0</td><td>17</td><td>18.1</td></tr>\n        <tr><td>8.5</td><td>Q½</td><td>58.3</td><td>18</td><td>18.5</td></tr>\n        <tr><td>9</td><td>R½</td><td>59.5</td><td>19</td><td>18.9</td></tr>\n        <tr><td>9.5</td><td>S½</td><td>60.8</td><td>21</td><td>19.3</td></tr>\n        <tr><td>10</td><td>T½</td><td>62.1</td><td>22</td><td>19.7</td></tr>\n        <tr><td>10.5</td><td>U½</td><td>63.4</td><td>23</td><td>20.1</td></tr>\n        <tr><td>11</td><td>V½</td><td>64.6</td><td>24</td><td>20.5</td></tr>\n        <tr><td>11.5</td><td>W½</td><td>65.9</td><td>26</td><td>20.9</td></tr>\n        <tr><td>12</td><td>X½</td><td>67.2</td><td>27</td><td>21.3</td></tr>\n        <tr><td>12.5</td><td>Y½</td><td>68.5</td><td>28</td><td>21.7</td></tr>\n        <tr><td>13</td><td>Z½</td><td>69.7</td><td>29</td><td>22.2</td></tr>\n      </tbody>\n    </table>\n    </div>\n    <p>Esta tabela cobre a faixa de meios-tamanhos em que a maioria dos anéis adultos é vendida (aproximadamente de um tamanho feminino pequeno a um masculino grande). Se a sua medida ficar um pouco fora dela, o conversor acima mostra a linha mais próxima em vez de se recusar a responder.</p>\n\n    <h2>Como medir o tamanho do seu anel em casa</h2>\n    <h3>Método 1: barbante ou tira de papel (mede a circunferência)</h3>\n    <ol>\n      <li>Corte uma tira fina de papel ou use um pedaço de barbante ou fita que não estique.</li>\n      <li>Enrole-a justa na base do dedo em que vai usar o anel — apertada o suficiente para não cair, folgada o suficiente para passar pela articulação.</li>\n      <li>Marque com caneta o ponto exato em que a tira se sobrepõe.</li>\n      <li>Estenda a tira sobre uma superfície plana e meça o comprimento marcado com uma régua, em milímetros.</li>\n      <li>Digite esse número no campo UE (circunferência, mm) acima para ver os tamanhos correspondentes dos EUA, do Reino Unido e do Japão/Coreia.</li>\n    </ol>\n    <h3>Método 2: um anel que já serve bem (mede o diâmetro interno)</h3>\n    <ol>\n      <li>Escolha um anel que já sirva confortavelmente no dedo pretendido — não um anel usado em outro dedo nem um anel muito largo, que fica mais apertado que um aro fino do mesmo tamanho.</li>\n      <li>Apoie o anel deitado sobre uma régua ou sobre um medidor de anéis impresso.</li>\n      <li>Meça em linha reta a abertura interna, no ponto mais largo, em milímetros.</li>\n      <li>Digite esse número no campo Diâmetro interno (mm) acima para ver os tamanhos correspondentes dos EUA, do Reino Unido, da UE e do Japão/Coreia.</li>\n    </ol>\n\n    <h2>Dicas para obter um tamanho preciso</h2>\n    <ul>\n      <li><strong>A hora do dia importa:</strong> os dedos incham um pouco ao longo do dia e no calor, e encolhem no frio. Meça à noite para obter o tamanho do dia a dia mais confiável e evite medir logo após exercícios ou em dias frios.</li>\n      <li><strong>Meça o dedo certo:</strong> o tamanho pode variar bastante entre dedos da mesma mão e até entre a mão esquerda e a direita.</li>\n      <li><strong>Aros largos pedem mais folga:</strong> um aro com mais de cerca de 6 mm de largura costuma precisar de meio tamanho a mais que um aro fino para dar a mesma sensação, pois há mais metal em contato com o dedo.</li>\n      <li><strong>Entre dois tamanhos?</strong> Subir de tamanho costuma ser mais seguro do que descer — um anel um pouco folgado pode ser diminuído com mais facilidade (e mais barato) do que um anel apertado pode ser alargado.</li>\n    </ul>\n\n    <h2>Por que uma tabela geral não substitui a medição profissional</h2>\n    <p>Ao contrário de tamanhos de sapato ou de roupa, o anel toca a pele diretamente, sem nenhuma folga embutida, então pequenos erros de medição pesam mais. A tabela deste conversor segue as tabelas de consulta padrão usadas no setor de joias, mas o tamanho da articulação, o formato do dedo e a largura e o metal específicos de um anel podem deslocar em meio tamanho aquilo que parece confortável. Para uma compra importante — sobretudo um anel de noivado — o medidor de anéis de metal de um joalheiro, experimentado pessoalmente, é sempre mais confiável do que um barbante ou uma tabela impressa.</p>\n",
  "de": "\n    <style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:13.5px}\n      .guide-content th,.guide-content td{text-align:center;padding:6px 8px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n      .guide-content .twrap{overflow-x:auto;margin:12px 0}\n      .guide-content .twrap table{margin:0;min-width:420px}\n    </style>\n\n\n    <h2>Eine Ringgrößentabelle ohne Rätselraten lesen</h2>\n    <p>Die Ringgröße gehört zum Verwirrendsten beim Online-Shopping: Die Systeme aus den USA/Kanada, Großbritannien/Australien, der EU und Japan/Korea zählen jeweils anders, und keines lässt sich per Kopfrechnen in ein anderes umrechnen. Dieser Umrechner erspart das Raten, indem er Ihre Größe direkt in einer veröffentlichten Ringgrößentabelle nachschlägt — dieselben Zahlen, die innen in echten Ringen eingraviert sind — statt eine Näherungsformel zu berechnen.</p>\n\n    <h2>Wie sich die Ringgrößensysteme unterscheiden</h2>\n    <ul>\n      <li><strong>USA / Kanada</strong> verwendet eine Zahlenskala von etwa 3 bis 16 mit halben Größen dazwischen (ein ganzer Größenschritt entspricht rund 0,4 mm Durchmesser).</li>\n      <li><strong>Großbritannien / Australien / Irland</strong> verwendet die Buchstaben A bis Z, wobei zwischen den meisten benachbarten US-Halbgrößen ein halber Buchstabe (½) liegt.</li>\n      <li><strong>EU (ISO 8653)</strong> ist als Fingerumfang in Millimetern definiert — eine EU-Größe 54 bedeutet also wörtlich 54 mm Umfang, für diesen Schritt ist kein Nachschlagen nötig.</li>\n      <li><strong>Japan / Korea (号)</strong> nutzt eine eigene aufsteigende Zahlenskala mit etwa einer Einheit je 1,3 mm Umfang; entscheidend ist: Japan und Korea verwenden exakt dieselben Zahlen, ein japanisches 号14 und ein koreanisches 14호 bezeichnen also denselben Ring.</li>\n      <li><strong>Innendurchmesser (mm)</strong> ist die geradlinige Breite der Öffnung statt des Abstands ringsherum — praktisch, wenn Sie einen vorhandenen Ring statt Ihres Fingers messen.</li>\n    </ul>\n\n    <div class=\"example\">\n      <p><strong>Rechenbeispiel.</strong> Ein Ring in US-Größe 7 entspricht UK N½, hat einen EU-Umfang von 54,4 mm, ist ein japanisch/koreanisches 号14 und hat 17,3 mm Innendurchmesser — alle vier Zahlen beschreiben exakt dieselbe physische Ringöffnung, nur anders gezählt.</p>\n    </div>\n\n    <h2>Vollständige Ringgrößen-Umrechnungstabelle</h2>\n    <p>Dies sind die vollständigen Nachschlagewerte, die dieser Umrechner verwendet — dieselben Zahlen speisen das interaktive Werkzeug oben, sodass ein Wechsel des Systems unter „Ich kenne meine Größe in“ immer zu einer Zeile unten passt.</p>\n<div class=\"twrap\">\n    <table>\n      <thead><tr><th>미국 / 캐나다</th><th>영국 / 호주</th><th>유럽 (mm)</th><th>일본 / 한국 (호)</th><th>안지름 (mm)</th></tr></thead>\n      <tbody>\n        <tr><td>3</td><td>F</td><td>44.0</td><td>4</td><td>14.1</td></tr>\n        <tr><td>3.5</td><td>G</td><td>45.5</td><td>5</td><td>14.5</td></tr>\n        <tr><td>4</td><td>H</td><td>46.8</td><td>7</td><td>14.9</td></tr>\n        <tr><td>4.5</td><td>I</td><td>48.0</td><td>8</td><td>15.3</td></tr>\n        <tr><td>5</td><td>J½</td><td>49.3</td><td>9</td><td>15.7</td></tr>\n        <tr><td>5.5</td><td>K½</td><td>50.6</td><td>10</td><td>16.1</td></tr>\n        <tr><td>6</td><td>L½</td><td>51.9</td><td>12</td><td>16.5</td></tr>\n        <tr><td>6.5</td><td>M½</td><td>53.1</td><td>13</td><td>16.9</td></tr>\n        <tr><td>7</td><td>N½</td><td>54.4</td><td>14</td><td>17.3</td></tr>\n        <tr><td>7.5</td><td>O½</td><td>55.7</td><td>15</td><td>17.7</td></tr>\n        <tr><td>8</td><td>P½</td><td>57.0</td><td>17</td><td>18.1</td></tr>\n        <tr><td>8.5</td><td>Q½</td><td>58.3</td><td>18</td><td>18.5</td></tr>\n        <tr><td>9</td><td>R½</td><td>59.5</td><td>19</td><td>18.9</td></tr>\n        <tr><td>9.5</td><td>S½</td><td>60.8</td><td>21</td><td>19.3</td></tr>\n        <tr><td>10</td><td>T½</td><td>62.1</td><td>22</td><td>19.7</td></tr>\n        <tr><td>10.5</td><td>U½</td><td>63.4</td><td>23</td><td>20.1</td></tr>\n        <tr><td>11</td><td>V½</td><td>64.6</td><td>24</td><td>20.5</td></tr>\n        <tr><td>11.5</td><td>W½</td><td>65.9</td><td>26</td><td>20.9</td></tr>\n        <tr><td>12</td><td>X½</td><td>67.2</td><td>27</td><td>21.3</td></tr>\n        <tr><td>12.5</td><td>Y½</td><td>68.5</td><td>28</td><td>21.7</td></tr>\n        <tr><td>13</td><td>Z½</td><td>69.7</td><td>29</td><td>22.2</td></tr>\n      </tbody>\n    </table>\n    </div>\n    <p>Diese Tabelle deckt den Halbgrößenbereich ab, in dem die meisten Ringe für Erwachsene verkauft werden (etwa von einer kleinen Damengröße bis zu einer großen Herrengröße). Liegt Ihre Messung knapp außerhalb, zeigt der Umrechner oben die nächstliegende Zeile an, statt die Antwort zu verweigern.</p>\n\n    <h2>So messen Sie Ihre Ringgröße zu Hause</h2>\n    <h3>Methode 1: Faden oder Papierstreifen (misst den Umfang)</h3>\n    <ol>\n      <li>Schneiden Sie einen schmalen Papierstreifen zu oder nehmen Sie ein Stück Faden oder Band, das sich nicht dehnt.</li>\n      <li>Legen Sie ihn eng um die Basis des Fingers, an dem Sie den Ring tragen möchten — eng genug, dass er hält, locker genug, um über den Knöchel zu gleiten.</li>\n      <li>Markieren Sie mit einem Stift genau die Stelle, an der sich der Streifen überlappt.</li>\n      <li>Legen Sie den Streifen flach hin und messen Sie die markierte Länge mit einem Lineal in Millimetern.</li>\n      <li>Geben Sie diese Zahl oben in das Feld EU (Umfang, mm) ein, um die passenden Größen für USA, UK und Japan/Korea zu sehen.</li>\n    </ol>\n    <h3>Methode 2: ein vorhandener, gut passender Ring (misst den Innendurchmesser)</h3>\n    <ol>\n      <li>Suchen Sie einen Ring, der am gewünschten Finger bereits bequem sitzt — keinen Ring von einem anderen Finger und keinen sehr breiten Statement-Ring, der enger sitzt als ein schmaler Ring derselben Größe.</li>\n      <li>Legen Sie den Ring flach auf ein Lineal oder auf eine ausdruckbare Ringgrößen-Schablone.</li>\n      <li>Messen Sie die innere Öffnung geradlinig an ihrer breitesten Stelle in Millimetern.</li>\n      <li>Geben Sie diese Zahl oben in das Feld Innendurchmesser (mm) ein, um die passenden Größen für USA, UK, EU und Japan/Korea zu sehen.</li>\n    </ol>\n\n    <h2>Tipps für eine genaue Größe</h2>\n    <ul>\n      <li><strong>Die Tageszeit zählt:</strong> Finger schwellen im Laufe des Tages und bei warmem Wetter leicht an und werden bei Kälte schmaler. Messen Sie abends für die verlässlichste Alltagsgröße und vermeiden Sie Messungen direkt nach dem Sport oder bei Kälte.</li>\n      <li><strong>Messen Sie genau den richtigen Finger:</strong> Die Ringgröße kann sich zwischen Fingern derselben Hand und sogar zwischen linker und rechter Hand deutlich unterscheiden.</li>\n      <li><strong>Breite Ringschienen brauchen mehr Platz:</strong> Eine Schiene breiter als etwa 6 mm muss meist eine halbe Größe größer sein als eine schmale, damit sie sich gleich anfühlt, da mehr Metall den Finger berührt.</li>\n      <li><strong>Zwischen zwei Größen?</strong> Aufrunden ist meist sicherer als abrunden — ein leicht zu weiter Ring lässt sich einfacher (und günstiger) verkleinern, als ein zu enger Ring geweitet werden kann.</li>\n    </ul>\n\n    <h2>Warum eine allgemeine Tabelle keine professionelle Größenbestimmung ersetzt</h2>\n    <p>Anders als Schuh- oder Kleidergrößen liegt ein Ring ohne jede Bewegungszugabe direkt auf der Haut, deshalb wiegen kleine Messfehler schwerer. Die Tabelle dieses Umrechners entspricht den im Schmuckhandel üblichen Standardtabellen, doch Knöchelgröße, Fingerform sowie Breite und Metall eines konkreten Rings können das angenehme Maß um eine halbe Größe verschieben. Für einen wichtigen Kauf — besonders einen Verlobungsring — ist ein vor Ort anprobiertes Ringmaß aus Metall beim Juwelier immer verlässlicher als ein Faden oder eine ausgedruckte Tabelle.</p>\n",
  "fr": "\n    <style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:13.5px}\n      .guide-content th,.guide-content td{text-align:center;padding:6px 8px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n      .guide-content .twrap{overflow-x:auto;margin:12px 0}\n      .guide-content .twrap table{margin:0;min-width:420px}\n    </style>\n\n\n    <h2>Lire un tableau des tailles de bagues sans deviner</h2>\n    <p>La taille de bague est l'une des choses les plus déroutantes à acheter en ligne : les systèmes américain/canadien, britannique/australien, européen et japonais/coréen comptent chacun différemment, et aucun ne se convertit dans un autre par un simple calcul mental. Ce convertisseur supprime les approximations en cherchant votre taille directement dans un tableau de tailles publié — les mêmes chiffres gravés à l'intérieur des vraies bagues — plutôt qu'en appliquant une formule approximative.</p>\n\n    <h2>En quoi les systèmes de tailles de bagues diffèrent</h2>\n    <ul>\n      <li><strong>États-Unis / Canada</strong> utilise une échelle numérique allant environ de 3 à 16, avec des demi-tailles intermédiaires (une taille entière correspond à environ 0,4 mm de diamètre).</li>\n      <li><strong>Royaume-Uni / Australie / Irlande</strong> utilise les lettres A à Z, avec un pas d'une demi-lettre (½) entre la plupart des demi-tailles américaines voisines.</li>\n      <li><strong>UE (ISO 8653)</strong> est défini comme la circonférence du doigt en millimètres — une taille européenne de 54 signifie donc littéralement une circonférence de 54 mm, sans besoin de conversion pour cette étape.</li>\n      <li><strong>Japon / Corée (号)</strong> utilise sa propre échelle numérique croissante, à raison d'environ une unité par 1,3 mm de circonférence ; surtout, le Japon et la Corée partagent exactement les mêmes chiffres, si bien qu'un 号14 japonais et un 14호 coréen désignent la même bague.</li>\n      <li><strong>Diamètre intérieur (mm)</strong> correspond à la largeur en ligne droite de l'ouverture plutôt qu'à la distance autour de celle-ci — utile lorsque vous mesurez une bague existante plutôt que votre doigt.</li>\n    </ul>\n\n    <div class=\"example\">\n      <p><strong>Exemple concret.</strong> Une bague de taille US 7 correspond à un N½ britannique, à une circonférence européenne de 54,4 mm, à un 号14 japonais/coréen et à un diamètre intérieur de 17,3 mm — ces quatre chiffres décrivent exactement la même ouverture physique, simplement comptée différemment.</p>\n    </div>\n\n    <h2>Tableau complet de conversion des tailles de bagues</h2>\n    <p>Voici les valeurs de correspondance complètes utilisées par ce convertisseur — ce sont les mêmes chiffres qui alimentent l'outil interactif ci-dessus, si bien que changer le système « Je connais ma taille en » correspond toujours à une ligne du tableau.</p>\n<div class=\"twrap\">\n    <table>\n      <thead><tr><th>미국 / 캐나다</th><th>영국 / 호주</th><th>유럽 (mm)</th><th>일본 / 한국 (호)</th><th>안지름 (mm)</th></tr></thead>\n      <tbody>\n        <tr><td>3</td><td>F</td><td>44.0</td><td>4</td><td>14.1</td></tr>\n        <tr><td>3.5</td><td>G</td><td>45.5</td><td>5</td><td>14.5</td></tr>\n        <tr><td>4</td><td>H</td><td>46.8</td><td>7</td><td>14.9</td></tr>\n        <tr><td>4.5</td><td>I</td><td>48.0</td><td>8</td><td>15.3</td></tr>\n        <tr><td>5</td><td>J½</td><td>49.3</td><td>9</td><td>15.7</td></tr>\n        <tr><td>5.5</td><td>K½</td><td>50.6</td><td>10</td><td>16.1</td></tr>\n        <tr><td>6</td><td>L½</td><td>51.9</td><td>12</td><td>16.5</td></tr>\n        <tr><td>6.5</td><td>M½</td><td>53.1</td><td>13</td><td>16.9</td></tr>\n        <tr><td>7</td><td>N½</td><td>54.4</td><td>14</td><td>17.3</td></tr>\n        <tr><td>7.5</td><td>O½</td><td>55.7</td><td>15</td><td>17.7</td></tr>\n        <tr><td>8</td><td>P½</td><td>57.0</td><td>17</td><td>18.1</td></tr>\n        <tr><td>8.5</td><td>Q½</td><td>58.3</td><td>18</td><td>18.5</td></tr>\n        <tr><td>9</td><td>R½</td><td>59.5</td><td>19</td><td>18.9</td></tr>\n        <tr><td>9.5</td><td>S½</td><td>60.8</td><td>21</td><td>19.3</td></tr>\n        <tr><td>10</td><td>T½</td><td>62.1</td><td>22</td><td>19.7</td></tr>\n        <tr><td>10.5</td><td>U½</td><td>63.4</td><td>23</td><td>20.1</td></tr>\n        <tr><td>11</td><td>V½</td><td>64.6</td><td>24</td><td>20.5</td></tr>\n        <tr><td>11.5</td><td>W½</td><td>65.9</td><td>26</td><td>20.9</td></tr>\n        <tr><td>12</td><td>X½</td><td>67.2</td><td>27</td><td>21.3</td></tr>\n        <tr><td>12.5</td><td>Y½</td><td>68.5</td><td>28</td><td>21.7</td></tr>\n        <tr><td>13</td><td>Z½</td><td>69.7</td><td>29</td><td>22.2</td></tr>\n      </tbody>\n    </table>\n    </div>\n    <p>Ce tableau couvre la plage de demi-tailles dans laquelle la plupart des bagues pour adultes sont vendues (d'une petite taille femme à une grande taille homme, environ). Si votre mesure sort légèrement de cette plage, le convertisseur ci-dessus affiche la ligne la plus proche au lieu de refuser de répondre.</p>\n\n    <h2>Comment mesurer votre tour de doigt chez vous</h2>\n    <h3>Méthode 1 : ficelle ou bande de papier (mesure la circonférence)</h3>\n    <ol>\n      <li>Découpez une fine bande de papier, ou utilisez un morceau de ficelle ou de ruban qui ne s'étire pas.</li>\n      <li>Enroulez-la bien ajustée autour de la base du doigt sur lequel vous porterez la bague — assez serrée pour tenir, assez lâche pour passer l'articulation.</li>\n      <li>Marquez au stylo le point exact où la bande se chevauche.</li>\n      <li>Posez la bande à plat et mesurez la longueur marquée avec une règle, en millimètres.</li>\n      <li>Saisissez ce nombre dans le champ UE (circonférence, mm) ci-dessus pour voir les tailles US, UK et Japon/Corée correspondantes.</li>\n    </ol>\n    <h3>Méthode 2 : une bague existante qui vous va déjà (mesure le diamètre intérieur)</h3>\n    <ol>\n      <li>Trouvez une bague qui va déjà confortablement au doigt visé — pas une bague portée à un autre doigt, ni une bague très large, qui serre davantage qu'un anneau fin de même taille.</li>\n      <li>Posez la bague à plat sur une règle, ou sur un gabarit de tailles de bagues imprimable.</li>\n      <li>Mesurez en ligne droite l'ouverture intérieure, à son point le plus large, en millimètres.</li>\n      <li>Saisissez ce nombre dans le champ Diamètre intérieur (mm) ci-dessus pour voir les tailles US, UK, UE et Japon/Corée correspondantes.</li>\n    </ol>\n\n    <h2>Conseils pour obtenir une taille précise</h2>\n    <ul>\n      <li><strong>L'heure de la journée compte :</strong> les doigts gonflent légèrement au fil de la journée et par temps chaud, et rétrécissent au froid. Mesurez le soir pour obtenir la taille quotidienne la plus fiable, et évitez de mesurer juste après le sport ou par temps froid.</li>\n      <li><strong>Mesurez le bon doigt :</strong> la taille de bague peut varier sensiblement d'un doigt à l'autre d'une même main, et même entre la main gauche et la main droite.</li>\n      <li><strong>Les anneaux larges demandent plus de place :</strong> un anneau de plus de 6 mm de large doit généralement faire une demi-taille de plus qu'un anneau fin pour un confort équivalent, car davantage de métal touche le doigt.</li>\n      <li><strong>Entre deux tailles ?</strong> Prendre la taille au-dessus est en général plus sûr : une bague un peu large se rétrécit plus facilement (et à moindre coût) qu'une bague trop serrée ne s'agrandit.</li>\n    </ul>\n\n    <h2>Pourquoi un tableau général ne remplace pas une mesure professionnelle</h2>\n    <p>Contrairement aux tailles de chaussures ou de vêtements, une bague touche directement la peau sans aucune aisance, si bien que de petites erreurs de mesure comptent davantage. Le tableau de ce convertisseur reprend les tables de correspondance standard utilisées dans la joaillerie, mais la taille de l'articulation, la forme du doigt ainsi que la largeur et le métal exacts d'une bague donnée peuvent modifier d'une demi-taille ce qui semble confortable. Pour un achat important — surtout une bague de fiançailles — un jeu de bagues-étalons en métal chez un bijoutier, essayé sur place, reste toujours plus fiable qu'une ficelle ou un tableau imprimé.</p>\n",
"ko": "\n    <style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:13.5px}\n      .guide-content th,.guide-content td{text-align:center;padding:6px 8px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n      .guide-content .twrap{overflow-x:auto;margin:12px 0}\n      .guide-content .twrap table{margin:0;min-width:420px}\n    </style>\n\n    <h2>추측 없이 반지 사이즈 표 읽는 법</h2>\n    <p>반지 사이즈는 온라인 쇼핑에서 가장 헷갈리는 항목 중 하나입니다. 미국/캐나다, 영국/호주, 유럽, 일본/한국 방식이 각각 다르게 세고, 어느 것도 간단한 암산으로 서로 변환되지 않습니다. 이 변환기는 근사 공식을 계산하는 대신, 실제 반지 안쪽에 각인되는 것과 같은 공식 반지 사이즈 표에서 곧바로 값을 찾아 추측을 없앱니다.</p>\n\n    <h2>반지 사이즈 체계는 어떻게 다른가</h2>\n    <ul>\n      <li><strong>미국 / 캐나다</strong>는 대략 3부터 16까지의 숫자 척도를 쓰며 그 사이에 반 사이즈가 있습니다(한 사이즈 간격은 지름 약 0.4 mm).</li>\n      <li><strong>영국 / 호주 / 아일랜드</strong>는 A부터 Z까지의 알파벳을 쓰고, 인접한 미국 반 사이즈 사이에 반 글자(½) 단계가 들어갑니다.</li>\n      <li><strong>유럽 (ISO 8653)</strong>은 손가락 둘레를 밀리미터로 나타낸 값입니다. 즉 EU 54는 말 그대로 둘레 54 mm를 뜻하므로 그 단계만큼은 표를 찾을 필요가 없습니다.</li>\n      <li><strong>일본 / 한국 (호)</strong>은 고유의 오름차순 숫자 척도로, 둘레 약 1.3 mm마다 1호씩 올라갑니다. 중요한 점은 일본과 한국이 완전히 같은 숫자를 쓴다는 것이라, 일본의 14호와 한국의 14호는 같은 반지입니다.</li>\n      <li><strong>안지름 (mm)</strong>은 둘레가 아니라 구멍을 가로지르는 직선 폭입니다. 손가락이 아니라 이미 가진 반지를 잴 때 유용합니다.</li>\n    </ul>\n\n    <div class=\"example\">\n      <p><strong>예시로 보기.</strong> 미국 7호 반지는 영국 N½, 유럽 둘레 54.4 mm, 일본/한국 14호이며 안지름은 17.3 mm입니다. 네 숫자 모두 똑같은 반지 구멍을 세는 방식만 달리 표현한 것입니다.</p>\n    </div>\n\n    <h2>반지 사이즈 변환 전체 표</h2>\n    <p>아래는 이 변환기가 사용하는 전체 대조 값입니다. 위 도구도 같은 숫자를 쓰므로 \"내가 아는 사이즈 기준\"을 바꿔도 항상 아래 행과 일치합니다.</p>\n    <div class=\"twrap\">\n    <table>\n      <thead><tr><th>미국 / 캐나다</th><th>영국 / 호주</th><th>유럽 (mm)</th><th>일본 / 한국 (호)</th><th>안지름 (mm)</th></tr></thead>\n      <tbody>\n        <tr><td>3</td><td>F</td><td>44.0</td><td>4</td><td>14.1</td></tr>\n        <tr><td>3.5</td><td>G</td><td>45.5</td><td>5</td><td>14.5</td></tr>\n        <tr><td>4</td><td>H</td><td>46.8</td><td>7</td><td>14.9</td></tr>\n        <tr><td>4.5</td><td>I</td><td>48.0</td><td>8</td><td>15.3</td></tr>\n        <tr><td>5</td><td>J½</td><td>49.3</td><td>9</td><td>15.7</td></tr>\n        <tr><td>5.5</td><td>K½</td><td>50.6</td><td>10</td><td>16.1</td></tr>\n        <tr><td>6</td><td>L½</td><td>51.9</td><td>12</td><td>16.5</td></tr>\n        <tr><td>6.5</td><td>M½</td><td>53.1</td><td>13</td><td>16.9</td></tr>\n        <tr><td>7</td><td>N½</td><td>54.4</td><td>14</td><td>17.3</td></tr>\n        <tr><td>7.5</td><td>O½</td><td>55.7</td><td>15</td><td>17.7</td></tr>\n        <tr><td>8</td><td>P½</td><td>57.0</td><td>17</td><td>18.1</td></tr>\n        <tr><td>8.5</td><td>Q½</td><td>58.3</td><td>18</td><td>18.5</td></tr>\n        <tr><td>9</td><td>R½</td><td>59.5</td><td>19</td><td>18.9</td></tr>\n        <tr><td>9.5</td><td>S½</td><td>60.8</td><td>21</td><td>19.3</td></tr>\n        <tr><td>10</td><td>T½</td><td>62.1</td><td>22</td><td>19.7</td></tr>\n        <tr><td>10.5</td><td>U½</td><td>63.4</td><td>23</td><td>20.1</td></tr>\n        <tr><td>11</td><td>V½</td><td>64.6</td><td>24</td><td>20.5</td></tr>\n        <tr><td>11.5</td><td>W½</td><td>65.9</td><td>26</td><td>20.9</td></tr>\n        <tr><td>12</td><td>X½</td><td>67.2</td><td>27</td><td>21.3</td></tr>\n        <tr><td>12.5</td><td>Y½</td><td>68.5</td><td>28</td><td>21.7</td></tr>\n        <tr><td>13</td><td>Z½</td><td>69.7</td><td>29</td><td>22.2</td></tr>\n      </tbody>\n    </table>\n    </div>\n    <p>이 표는 성인용 반지가 판매되는 대부분의 반 사이즈 범위(작은 여성 사이즈부터 큰 남성 사이즈까지)를 담고 있습니다. 측정값이 범위를 살짝 벗어나면 위 변환기는 답을 거부하는 대신 가장 가까운 행을 보여 줍니다.</p>\n\n    <h2>집에서 반지 사이즈 재는 법</h2>\n    <h3>방법 1: 실 또는 종이띠 (둘레 측정)</h3>\n    <ol>\n      <li>얇은 종이띠를 자르거나, 늘어나지 않는 실이나 리본을 준비합니다.</li>\n      <li>반지를 낄 손가락 뿌리에 알맞게 감습니다. 빠지지 않을 만큼 조이되 관절을 넘어갈 만큼은 여유 있게.</li>\n      <li>띠가 겹치는 지점을 펜으로 정확히 표시합니다.</li>\n      <li>띠를 펴서 표시한 길이를 자로 밀리미터 단위로 잽니다.</li>\n      <li>그 숫자를 위의 유럽(둘레, mm) 칸에 입력하면 미국·영국·일본/한국 사이즈가 나옵니다.</li>\n    </ol>\n    <h3>방법 2: 이미 잘 맞는 반지 (안지름 측정)</h3>\n    <ol>\n      <li>해당 손가락에 편안하게 맞는 반지를 고릅니다. 다른 손가락에 끼던 반지나, 같은 사이즈라도 더 꽉 끼는 아주 두꺼운 반지는 피하세요.</li>\n      <li>반지를 자 위에, 또는 출력한 반지 사이즈 차트 위에 평평하게 놓습니다.</li>\n      <li>안쪽 구멍의 가장 넓은 부분을 가로질러 밀리미터로 잽니다.</li>\n      <li>그 숫자를 위의 안지름(mm) 칸에 입력하면 미국·영국·유럽·일본/한국 사이즈가 나옵니다.</li>\n    </ol>\n\n    <h2>정확하게 재기 위한 요령</h2>\n    <ul>\n      <li><strong>재는 시간이 중요합니다:</strong> 손가락은 하루가 지나면서, 그리고 더운 날씨에 약간 붓고 추울 때 줄어듭니다. 일상적으로 가장 믿을 만한 사이즈는 저녁에 잰 값이며, 운동 직후나 추운 날의 측정은 피하세요.</li>\n      <li><strong>낄 손가락을 그대로 재세요:</strong> 같은 손이라도 손가락마다, 심지어 왼손과 오른손 사이에도 사이즈가 눈에 띄게 다를 수 있습니다.</li>\n      <li><strong>넓은 반지는 여유가 더 필요합니다:</strong> 폭이 약 6 mm를 넘는 반지는 같은 착용감을 내려면 보통 얇은 반지보다 반 사이즈 커야 합니다. 금속이 손가락에 닿는 면적이 넓기 때문입니다.</li>\n      <li><strong>두 사이즈 사이라면?</strong> 대개 큰 쪽이 안전합니다. 조금 헐렁한 반지를 줄이는 편이 너무 꽉 끼는 반지를 늘리는 것보다 쉽고 비용도 적게 듭니다.</li>\n    </ul>\n\n    <h2>일반 표가 전문 사이즈 측정을 대신할 수 없는 이유</h2>\n    <p>신발이나 옷 사이즈와 달리 반지는 여유분 없이 피부에 바로 닿기 때문에 작은 측정 오차도 더 크게 느껴집니다. 이 변환기의 표는 주얼리 업계에서 널리 쓰이는 표준 대조표를 따르지만, 관절 크기와 손가락 모양, 특정 반지의 폭과 소재에 따라 편안한 사이즈가 반 사이즈까지 달라질 수 있습니다. 중요한 구매, 특히 약혼 반지라면 매장에서 직접 착용해 보는 금속 링 게이지가 실이나 인쇄된 표보다 언제나 더 정확합니다.</p>\n",
"ja": "\n    <style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:13.5px}\n      .guide-content th,.guide-content td{text-align:center;padding:6px 8px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n      .guide-content .twrap{overflow-x:auto;margin:12px 0}\n      .guide-content .twrap table{margin:0;min-width:420px}\n    </style>\n\n    <h2>当てずっぽうなしでリングサイズ表を読む</h2>\n    <p>リングサイズはオンラインで最も分かりにくい買い物のひとつです。米国/カナダ、英国/オーストラリア、EU、日本/韓国の各方式は数え方が違い、暗算で簡単に換算できるものはひとつもありません。このコンバーターは概算式で計算するのではなく、実際の指輪の内側に刻印されるのと同じ公表されたリングサイズ表を直接参照するので、推測が要りません。</p>\n\n    <h2>リングサイズ体系の違い</h2>\n    <ul>\n      <li><strong>米国 / カナダ</strong>はおよそ3から16までの数字で、その間にハーフサイズがあります（1サイズの差は直径で約0.4 mm）。</li>\n      <li><strong>英国 / オーストラリア / アイルランド</strong>はAからZのアルファベットを用い、隣り合う米国のハーフサイズの間にハーフレター（½）の刻みが入ります。</li>\n      <li><strong>EU（ISO 8653）</strong>は指の円周をミリメートルで表したものです。つまりEUの54は文字どおり円周54 mmを意味し、その段階については参照表が不要です。</li>\n      <li><strong>日本 / 韓国（号）</strong>は独自の昇順の数値で、円周およそ1.3 mmごとに1号上がります。重要なのは日本と韓国がまったく同じ番号を使うことで、日本の14号と韓国の14호は同じ指輪です。</li>\n      <li><strong>内径（mm）</strong>は周囲ではなく開口部をまっすぐ横切る幅です。指ではなく手持ちの指輪を測るときに役立ちます。</li>\n    </ul>\n\n    <div class=\"example\">\n      <p><strong>具体例。</strong> 米国サイズ7の指輪は英国N½、EUの円周54.4 mm、日本/韓国の14号で、内径は17.3 mmです。4つの数字はすべてまったく同じ指輪の開口部を、数え方だけ変えて表しています。</p>\n    </div>\n\n    <h2>リングサイズ換算表（全体）</h2>\n    <p>以下がこのコンバーターで使用している参照値のすべてです。上部のツールも同じ数字を使うため、「サイズが分かっている方式」を切り替えても常に下の行と一致します。</p>\n    <div class=\"twrap\">\n    <table>\n      <thead><tr><th>米国 / カナダ</th><th>英国 / 豪州</th><th>EU (mm)</th><th>日本 / 韓国 (号)</th><th>内径 (mm)</th></tr></thead>\n      <tbody>\n        <tr><td>3</td><td>F</td><td>44.0</td><td>4</td><td>14.1</td></tr>\n        <tr><td>3.5</td><td>G</td><td>45.5</td><td>5</td><td>14.5</td></tr>\n        <tr><td>4</td><td>H</td><td>46.8</td><td>7</td><td>14.9</td></tr>\n        <tr><td>4.5</td><td>I</td><td>48.0</td><td>8</td><td>15.3</td></tr>\n        <tr><td>5</td><td>J½</td><td>49.3</td><td>9</td><td>15.7</td></tr>\n        <tr><td>5.5</td><td>K½</td><td>50.6</td><td>10</td><td>16.1</td></tr>\n        <tr><td>6</td><td>L½</td><td>51.9</td><td>12</td><td>16.5</td></tr>\n        <tr><td>6.5</td><td>M½</td><td>53.1</td><td>13</td><td>16.9</td></tr>\n        <tr><td>7</td><td>N½</td><td>54.4</td><td>14</td><td>17.3</td></tr>\n        <tr><td>7.5</td><td>O½</td><td>55.7</td><td>15</td><td>17.7</td></tr>\n        <tr><td>8</td><td>P½</td><td>57.0</td><td>17</td><td>18.1</td></tr>\n        <tr><td>8.5</td><td>Q½</td><td>58.3</td><td>18</td><td>18.5</td></tr>\n        <tr><td>9</td><td>R½</td><td>59.5</td><td>19</td><td>18.9</td></tr>\n        <tr><td>9.5</td><td>S½</td><td>60.8</td><td>21</td><td>19.3</td></tr>\n        <tr><td>10</td><td>T½</td><td>62.1</td><td>22</td><td>19.7</td></tr>\n        <tr><td>10.5</td><td>U½</td><td>63.4</td><td>23</td><td>20.1</td></tr>\n        <tr><td>11</td><td>V½</td><td>64.6</td><td>24</td><td>20.5</td></tr>\n        <tr><td>11.5</td><td>W½</td><td>65.9</td><td>26</td><td>20.9</td></tr>\n        <tr><td>12</td><td>X½</td><td>67.2</td><td>27</td><td>21.3</td></tr>\n        <tr><td>12.5</td><td>Y½</td><td>68.5</td><td>28</td><td>21.7</td></tr>\n        <tr><td>13</td><td>Z½</td><td>69.7</td><td>29</td><td>22.2</td></tr>\n      </tbody>\n    </table>\n    </div>\n    <p>この表は成人用の指輪が販売されるハーフサイズの範囲（小さめの女性サイズから大きめの男性サイズまで）をカバーしています。測定値がわずかに範囲外でも、上のコンバーターは回答を拒まず最も近い行を表示します。</p>\n\n    <h2>自宅でリングサイズを測る方法</h2>\n    <h3>方法1：紙帯や糸を使う（円周を測る）</h3>\n    <ol>\n      <li>細い紙帯を切るか、伸びない糸やリボンを用意します。</li>\n      <li>指輪をはめる指の付け根にぴったり巻きます。落ちない程度に締め、関節を通るくらいの余裕は残します。</li>\n      <li>帯が重なる位置をペンで正確に印を付けます。</li>\n      <li>帯を平らに伸ばし、印までの長さを定規でミリメートル単位で測ります。</li>\n      <li>その数値を上のEU（円周、mm）欄に入力すると、米国・英国・日本/韓国のサイズが分かります。</li>\n    </ol>\n    <h3>方法2：すでにぴったりの指輪を使う（内径を測る）</h3>\n    <ol>\n      <li>その指にちょうど良く合っている指輪を選びます。別の指用の指輪や、同じサイズでもきつく感じる幅広のデザインリングは避けてください。</li>\n      <li>指輪を定規の上、または印刷したリングサイズ表の上に平らに置きます。</li>\n      <li>内側の開口部の最も広いところをまっすぐ横切ってミリメートルで測ります。</li>\n      <li>その数値を上の内径（mm）欄に入力すると、米国・英国・EU・日本/韓国のサイズが分かります。</li>\n    </ol>\n\n    <h2>正確に測るためのコツ</h2>\n    <ul>\n      <li><strong>測る時間帯が影響します：</strong> 指は1日のうちに、また暑い時期にわずかにむくみ、寒いと細くなります。普段使いに最も信頼できるのは夕方の測定で、運動直後や寒い日の測定は避けましょう。</li>\n      <li><strong>実際にはめる指を測る：</strong> 同じ手でも指ごとに、さらには左右の手でもサイズがはっきり違うことがあります。</li>\n      <li><strong>幅広のリングは余裕が必要：</strong> 幅が約6 mmを超えるリングは、同じ着け心地にするには細いリングより通常ハーフサイズ大きめが必要です。金属が指に触れる面積が広いためです。</li>\n      <li><strong>2つのサイズの中間なら？</strong> 通常は大きい方が安全です。少し緩い指輪を小さく直すほうが、きつすぎる指輪を広げるより簡単で費用も抑えられます。</li>\n    </ul>\n\n    <h2>一般的な表が専門店の採寸の代わりにならない理由</h2>\n    <p>靴や衣類のサイズと違い、指輪はゆとりなしに直接肌に触れるため、わずかな測定誤差の影響が大きくなります。このコンバーターの表は宝飾業界で広く使われる標準的な参照表に基づいていますが、関節の太さ、指の形、その指輪特有の幅や素材によって、心地よいサイズは半サイズほどずれることがあります。大切な購入、特に婚約指輪では、店頭で実際に試す金属製のリングゲージが糸や印刷した表よりも常に確実です。</p>\n",
"zh": "\n    <style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:13.5px}\n      .guide-content th,.guide-content td{text-align:center;padding:6px 8px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n      .guide-content .twrap{overflow-x:auto;margin:12px 0}\n      .guide-content .twrap table{margin:0;min-width:420px}\n    </style>\n\n    <h2>看懂戒指尺寸对照表，不再靠猜</h2>\n    <p>戒指尺寸是网购中最容易搞混的项目之一：美国/加拿大、英国/澳大利亚、欧盟以及日本/韩国各有各的计数方式，彼此都无法用简单心算换算。本换算器不用近似公式估算，而是直接在公开的戒指尺寸对照表中查找——正是刻在真实戒指内圈的那组数字，因此无需猜测。</p>\n\n    <h2>各种戒指尺寸体系有何不同</h2>\n    <ul>\n      <li><strong>美国 / 加拿大</strong>采用大约从3到16的数字刻度，中间设有半码（一个整码相差约0.4 mm直径）。</li>\n      <li><strong>英国 / 澳大利亚 / 爱尔兰</strong>使用字母A到Z，相邻的美国半码之间通常隔着一个半字母（½）。</li>\n      <li><strong>欧盟（ISO 8653）</strong>定义为手指周长的毫米数——所以欧盟尺寸54就是字面上的周长54 mm，这一步本身无需查表。</li>\n      <li><strong>日本 / 韩国（号）</strong>使用自成体系的递增数字，周长每增加约1.3 mm加一号；关键在于日本和韩国使用完全相同的号数，所以日本的14号和韩国的14호是同一枚戒指。</li>\n      <li><strong>内径（mm）</strong>指的是开口的直线宽度而非一圈的长度——量现有戒指而不是量手指时最有用。</li>\n    </ul>\n\n    <div class=\"example\">\n      <p><strong>实例。</strong> 一枚美国7号戒指对应英国N½、欧盟周长54.4 mm、日本/韩国14号，内径为17.3 mm——这四个数字描述的是完全相同的戒圈开口，只是计数方式不同。</p>\n    </div>\n\n    <h2>完整戒指尺寸换算表</h2>\n    <p>以下是本换算器使用的全部查表数据——上方的互动工具用的是同一组数字，因此在那里切换“我知道的尺寸制式”时，结果始终与下表某一行一致。</p>\n    <div class=\"twrap\">\n    <table>\n      <thead><tr><th>美国 / 加拿大</th><th>英国 / 澳大利亚</th><th>欧盟 (mm)</th><th>日本 / 韩国 (号)</th><th>内径 (mm)</th></tr></thead>\n      <tbody>\n        <tr><td>3</td><td>F</td><td>44.0</td><td>4</td><td>14.1</td></tr>\n        <tr><td>3.5</td><td>G</td><td>45.5</td><td>5</td><td>14.5</td></tr>\n        <tr><td>4</td><td>H</td><td>46.8</td><td>7</td><td>14.9</td></tr>\n        <tr><td>4.5</td><td>I</td><td>48.0</td><td>8</td><td>15.3</td></tr>\n        <tr><td>5</td><td>J½</td><td>49.3</td><td>9</td><td>15.7</td></tr>\n        <tr><td>5.5</td><td>K½</td><td>50.6</td><td>10</td><td>16.1</td></tr>\n        <tr><td>6</td><td>L½</td><td>51.9</td><td>12</td><td>16.5</td></tr>\n        <tr><td>6.5</td><td>M½</td><td>53.1</td><td>13</td><td>16.9</td></tr>\n        <tr><td>7</td><td>N½</td><td>54.4</td><td>14</td><td>17.3</td></tr>\n        <tr><td>7.5</td><td>O½</td><td>55.7</td><td>15</td><td>17.7</td></tr>\n        <tr><td>8</td><td>P½</td><td>57.0</td><td>17</td><td>18.1</td></tr>\n        <tr><td>8.5</td><td>Q½</td><td>58.3</td><td>18</td><td>18.5</td></tr>\n        <tr><td>9</td><td>R½</td><td>59.5</td><td>19</td><td>18.9</td></tr>\n        <tr><td>9.5</td><td>S½</td><td>60.8</td><td>21</td><td>19.3</td></tr>\n        <tr><td>10</td><td>T½</td><td>62.1</td><td>22</td><td>19.7</td></tr>\n        <tr><td>10.5</td><td>U½</td><td>63.4</td><td>23</td><td>20.1</td></tr>\n        <tr><td>11</td><td>V½</td><td>64.6</td><td>24</td><td>20.5</td></tr>\n        <tr><td>11.5</td><td>W½</td><td>65.9</td><td>26</td><td>20.9</td></tr>\n        <tr><td>12</td><td>X½</td><td>67.2</td><td>27</td><td>21.3</td></tr>\n        <tr><td>12.5</td><td>Y½</td><td>68.5</td><td>28</td><td>21.7</td></tr>\n        <tr><td>13</td><td>Z½</td><td>69.7</td><td>29</td><td>22.2</td></tr>\n      </tbody>\n    </table>\n    </div>\n    <p>此表涵盖成人戒指常见的半码区间（约从偏小的女款到偏大的男款）。如果你的测量值略微超出范围，上方的换算器会显示最接近的一行，而不是拒绝给出答案。</p>\n\n    <h2>如何在家测量戒指尺寸</h2>\n    <h3>方法一：细绳或纸条（测周长）</h3>\n    <ol>\n      <li>裁一条细纸条，或使用不会拉伸的绳子或丝带。</li>\n      <li>把它贴合地绕在要戴戒指那根手指的根部——松紧以不会滑落、又能越过指节为准。</li>\n      <li>用笔在纸条相互重叠的位置精确做记号。</li>\n      <li>把纸条摊平，用直尺以毫米为单位量出记号处的长度。</li>\n      <li>把这个数字填入上方的“欧盟（周长，mm）”栏，即可看到对应的美国、英国和日本/韩国尺寸。</li>\n    </ol>\n    <h3>方法二：一枚已经合适的戒指（测内径）</h3>\n    <ol>\n      <li>找一枚戴在目标手指上刚好舒适的戒指——不要用戴在别的手指上的戒指，也不要用很宽的夸张款，同样号数下宽戒会更紧。</li>\n      <li>把戒指平放在直尺上，或放在打印好的戒指尺寸对照卡上。</li>\n      <li>以毫米为单位，横穿内圈开口最宽处测量。</li>\n      <li>把这个数字填入上方的“内径（mm）”栏，即可看到对应的美国、英国、欧盟和日本/韩国尺寸。</li>\n    </ol>\n\n    <h2>测得更准确的几点建议</h2>\n    <ul>\n      <li><strong>时间点会有影响：</strong> 手指在一天之中以及天热时会略微肿胀，天冷时则会变细。想得到最贴合日常的尺寸，请在傍晚测量，并避免刚运动完或天气很冷时测量。</li>\n      <li><strong>量要戴的那根手指：</strong> 同一只手不同手指的戒指尺寸可能明显不同，左右手之间也会有差异。</li>\n      <li><strong>宽戒圈需要更多余量：</strong> 宽度超过约6 mm的戒圈通常要比同样感觉的细戒圈大半码，因为接触手指的金属面积更大。</li>\n      <li><strong>正好卡在两个尺寸之间？</strong> 通常往大取更保险——稍松的戒指改小比过紧的戒指撑大更容易，也更便宜。</li>\n    </ul>\n\n    <h2>为什么通用对照表不能取代专业量圈</h2>\n    <p>与鞋码或服装尺码不同，戒指直接贴着皮肤且没有预留松量，因此小小的测量误差影响更大。本换算器的表格与珠宝行业通用的标准查表数据一致，但指节大小、手指形状以及某枚戒指的具体宽度和材质，都可能让舒适尺寸相差半码。对于重要的购买——尤其是订婚戒指——到店试戴金属戒指量圈始终比用绳子或打印的表格更可靠。</p>\n",
"es": "\n    <style>\n      .guide-content{max-width:none;margin:32px 0 8px;line-height:1.7}\n      .guide-content h2{font-size:22px;font-weight:700;margin:28px 0 10px;letter-spacing:-.01em}\n      .guide-content h3{font-size:17px;font-weight:650;margin:20px 0 6px}\n      .guide-content p{margin:0 0 12px;color:var(--ink)}\n      .guide-content ul,.guide-content ol{margin:0 0 12px;padding-left:22px}\n      .guide-content li{margin:4px 0}\n      .guide-content .example{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:color-mix(in srgb,var(--accent) 5%,var(--surface))}\n      .guide-content table{width:100%;border-collapse:collapse;margin:12px 0;font-size:13.5px}\n      .guide-content th,.guide-content td{text-align:center;padding:6px 8px;border-bottom:1px solid var(--line)}\n      .guide-content th{color:var(--muted);font-weight:650}\n      .guide-content .twrap{overflow-x:auto;margin:12px 0}\n      .guide-content .twrap table{margin:0;min-width:420px}\n    </style>\n\n    <h2>Cómo leer una tabla de tallas de anillos sin adivinar</h2>\n    <p>La talla de anillo es una de las cosas más confusas de comprar por internet: los sistemas de EE. UU./Canadá, Reino Unido/Australia, la UE y Japón/Corea cuentan de forma distinta, y ninguno se convierte a otro con un cálculo mental sencillo. Este conversor elimina las conjeturas buscando tu talla directamente en una tabla de tallas publicada —los mismos números grabados dentro de los anillos reales— en lugar de aplicar una fórmula aproximada.</p>\n\n    <h2>En qué se diferencian los sistemas de tallas</h2>\n    <ul>\n      <li><strong>EE. UU. / Canadá</strong> usa una escala numérica que va aproximadamente del 3 al 16, con medias tallas intermedias (un paso de talla completa equivale a unos 0,4 mm de diámetro).</li>\n      <li><strong>Reino Unido / Australia / Irlanda</strong> usa letras de la A a la Z, con un paso de media letra (½) entre la mayoría de las medias tallas estadounidenses contiguas.</li>\n      <li><strong>UE (ISO 8653)</strong> se define como la circunferencia del dedo en milímetros: una talla europea 54 significa literalmente 54 mm de contorno, sin necesidad de consultar tabla para ese paso.</li>\n      <li><strong>Japón / Corea (号)</strong> usa su propia escala numérica ascendente, con aproximadamente una unidad por cada 1,3 mm de circunferencia; lo importante es que Japón y Corea comparten exactamente los mismos números, así que un 号14 japonés y un 14호 coreano son el mismo anillo.</li>\n      <li><strong>Diámetro interior (mm)</strong> es el ancho en línea recta de la abertura, no el contorno: útil cuando mides un anillo que ya tienes en lugar de tu dedo.</li>\n    </ul>\n\n    <div class=\"example\">\n      <p><strong>Ejemplo resuelto.</strong> Un anillo de talla 7 de EE. UU. es un N½ británico, tiene una circunferencia europea de 54,4 mm, es un 号14 de Japón/Corea y mide 17,3 mm de diámetro interior: los cuatro números describen exactamente la misma abertura, solo que contada de distinta manera.</p>\n    </div>\n\n    <h2>Tabla completa de equivalencias de tallas de anillo</h2>\n    <p>Estos son todos los valores de consulta que usa este conversor; la herramienta interactiva de arriba usa los mismos números, así que cambiar el sistema en «Sé mi talla en» siempre coincide con una fila de abajo.</p>\n    <div class=\"twrap\">\n    <table>\n      <thead><tr><th>EE. UU. / CA</th><th>RU / AU</th><th>UE (mm)</th><th>Japón / Corea (号)</th><th>Diámetro (mm)</th></tr></thead>\n      <tbody>\n        <tr><td>3</td><td>F</td><td>44.0</td><td>4</td><td>14.1</td></tr>\n        <tr><td>3.5</td><td>G</td><td>45.5</td><td>5</td><td>14.5</td></tr>\n        <tr><td>4</td><td>H</td><td>46.8</td><td>7</td><td>14.9</td></tr>\n        <tr><td>4.5</td><td>I</td><td>48.0</td><td>8</td><td>15.3</td></tr>\n        <tr><td>5</td><td>J½</td><td>49.3</td><td>9</td><td>15.7</td></tr>\n        <tr><td>5.5</td><td>K½</td><td>50.6</td><td>10</td><td>16.1</td></tr>\n        <tr><td>6</td><td>L½</td><td>51.9</td><td>12</td><td>16.5</td></tr>\n        <tr><td>6.5</td><td>M½</td><td>53.1</td><td>13</td><td>16.9</td></tr>\n        <tr><td>7</td><td>N½</td><td>54.4</td><td>14</td><td>17.3</td></tr>\n        <tr><td>7.5</td><td>O½</td><td>55.7</td><td>15</td><td>17.7</td></tr>\n        <tr><td>8</td><td>P½</td><td>57.0</td><td>17</td><td>18.1</td></tr>\n        <tr><td>8.5</td><td>Q½</td><td>58.3</td><td>18</td><td>18.5</td></tr>\n        <tr><td>9</td><td>R½</td><td>59.5</td><td>19</td><td>18.9</td></tr>\n        <tr><td>9.5</td><td>S½</td><td>60.8</td><td>21</td><td>19.3</td></tr>\n        <tr><td>10</td><td>T½</td><td>62.1</td><td>22</td><td>19.7</td></tr>\n        <tr><td>10.5</td><td>U½</td><td>63.4</td><td>23</td><td>20.1</td></tr>\n        <tr><td>11</td><td>V½</td><td>64.6</td><td>24</td><td>20.5</td></tr>\n        <tr><td>11.5</td><td>W½</td><td>65.9</td><td>26</td><td>20.9</td></tr>\n        <tr><td>12</td><td>X½</td><td>67.2</td><td>27</td><td>21.3</td></tr>\n        <tr><td>12.5</td><td>Y½</td><td>68.5</td><td>28</td><td>21.7</td></tr>\n        <tr><td>13</td><td>Z½</td><td>69.7</td><td>29</td><td>22.2</td></tr>\n      </tbody>\n    </table>\n    </div>\n    <p>Esta tabla cubre el rango de medias tallas en el que se vende la mayoría de los anillos para adultos (desde una talla de mujer pequeña hasta una de hombre grande). Si tu medida queda ligeramente fuera, el conversor de arriba muestra la fila más próxima en lugar de negarse a responder.</p>\n\n    <h2>Cómo medir tu talla de anillo en casa</h2>\n    <h3>Método 1: cordel o tira de papel (mide la circunferencia)</h3>\n    <ol>\n      <li>Corta una tira fina de papel, o usa un cordel o cinta que no se estire.</li>\n      <li>Enróllala ceñida en la base del dedo donde llevarás el anillo: lo bastante ajustada para que no se caiga y lo bastante holgada para pasar el nudillo.</li>\n      <li>Marca con un bolígrafo el punto exacto donde la tira se superpone.</li>\n      <li>Extiende la tira plana y mide con una regla la longitud marcada, en milímetros.</li>\n      <li>Introduce ese número en el campo UE (circunferencia, mm) de arriba para ver las tallas equivalentes de EE. UU., Reino Unido y Japón/Corea.</li>\n    </ol>\n    <h3>Método 2: un anillo que ya te queda bien (mide el diámetro interior)</h3>\n    <ol>\n      <li>Busca un anillo que ya quede cómodo en el dedo previsto: no uno que lleves en otro dedo ni un anillo muy ancho, que aprieta más que una alianza fina de la misma talla.</li>\n      <li>Coloca el anillo plano sobre una regla o sobre una plantilla de tallas impresa.</li>\n      <li>Mide en línea recta la abertura interior, por su punto más ancho, en milímetros.</li>\n      <li>Introduce ese número en el campo Diámetro interior (mm) de arriba para ver las tallas equivalentes de EE. UU., Reino Unido, UE y Japón/Corea.</li>\n    </ol>\n\n    <h2>Consejos para obtener una medida precisa</h2>\n    <ul>\n      <li><strong>La hora del día importa:</strong> los dedos se hinchan algo a lo largo del día y con el calor, y se estrechan con el frío. Mide por la tarde para obtener la talla más fiable para el día a día, y evita medir justo después de hacer ejercicio o con frío.</li>\n      <li><strong>Mide el dedo exacto:</strong> la talla puede variar bastante entre dedos de la misma mano, e incluso entre la mano izquierda y la derecha.</li>\n      <li><strong>Las alianzas anchas piden más holgura:</strong> un aro de más de unos 6 mm de ancho suele necesitar media talla más que uno fino para sentirse igual, porque hay más metal en contacto con el dedo.</li>\n      <li><strong>¿Entre dos tallas?</strong> Suele ser más seguro subir de talla: un anillo algo holgado se reduce con más facilidad (y más barato) de lo que se estira uno demasiado apretado.</li>\n    </ul>\n\n    <h2>Por qué una tabla general no sustituye a una medición profesional</h2>\n    <p>A diferencia del calzado o la ropa, el anillo toca la piel directamente y sin holgura, así que los pequeños errores de medida pesan más. La tabla de este conversor coincide con las tablas estándar que se usan en el sector de la joyería, pero el tamaño del nudillo, la forma del dedo y el ancho y el metal concretos de cada anillo pueden desplazar media talla lo que resulta cómodo. Para una compra importante —sobre todo un anillo de compromiso— un medidor de anillos metálico probado en persona en una joyería siempre es más fiable que un cordel o una tabla impresa.</p>\n"
};
